// RNICA VISIT HEADER LINKAGE (Phase 1)
// ---------------------------------------------------------------------------
// The RN Initial Comprehensive Assessment has historically had NO link to
// the authoritative Visit entity (see POST /visits/ -> create_visit(),
// the same engine VisitNotes.jsx's "Add New Visit" card and this file's
// own CHHAVisitNoteCard already use). This cache ensures exactly ONE Visit
// is minted per patient's initial RN ICA -- never a second, RNICA-specific
// shadow Visit system, and never a duplicate Visit on every autosave.
// Keyed by patientId; holds the in-flight/settled creation promise so
// concurrent saves (e.g. a fast double-click, or two autosave timers
// racing) can't mint two Visits for the same initial assessment.
const _rnicaVisitIdPromises = new Map();

function _rnicaVisitScheduleType(visitKind) {
  const normalized = String(visitKind || "").trim().toLowerCase();
  if (normalized === "unscheduled") return "UNSCHEDULED";
  if (normalized === "scheduled") return "SCHEDULED";
  return null;
}

function _rnicaVisitDatetime(visitMeta) {
  const visitDate = visitMeta?.visitDate;
  if (!visitDate) return null;
  const timeIn = visitMeta?.timeIn;
  return timeIn ? `${visitDate}T${timeIn}` : visitDate;
}

/**
 * Ensures the current patient's RN Initial Comprehensive Assessment has an
 * authoritative Visit (visit_type=RN, form_type=INITIAL_ICA) and returns
 * its id. Never called for "update"/"recert" subtype saves -- those are a
 * distinct ongoing-visit workflow, not this one-time admission document,
 * and are intentionally out of scope here. Failures are swallowed (a
 * Visit-Header linkage problem must never block the RN from saving their
 * clinical documentation) -- the assessment is simply saved without a
 * visit_id, and the next save attempt will retry.
 */
async function ensureRnicaVisitId(patientId, formData) {
  if (!patientId) return null;
  if (!_rnicaVisitIdPromises.has(patientId)) {
    const visitMeta = formData?.visitMeta || {};
    const promise = createVisitNote({
      patient_id: patientId,
      visit_type: "RN",
      service_type: "SN",
      form_type: "INITIAL_ICA",
      level_of_care: visitMeta.careLevel || null,
      visit_schedule_type: _rnicaVisitScheduleType(visitMeta.visitKind),
      visit_datetime: _rnicaVisitDatetime(visitMeta),
    })
      .then((result) => result?.visit_id || null)
      .catch((error) => {
        console.error("RNICA Visit Header linkage: failed to create the authoritative Visit", error);
        _rnicaVisitIdPromises.delete(patientId);
        return null;
      });
    _rnicaVisitIdPromises.set(patientId, promise);
  }
  return _rnicaVisitIdPromises.get(patientId);
}

// Delegates to the shared client so requests carry the auth token.
const api = {
  saveRNICAAssessment: async (patientId, formData, assessmentSubtype) => {
    // Only the true initial-assessment create (no subtype) mints the
    // RNICA Visit Header -- "update"/"recert" subtype saves document an
    // ongoing RN visit, a separate workflow not covered by this phase.
    const visitId = assessmentSubtype ? null : await ensureRnicaVisitId(patientId, formData);
    return saveRnicaAssessmentOffline(
      assessmentSubtype
        ? { patientId, formData, assessmentSubtype }
        : { patientId, formData, ...(visitId ? { visitId } : {}) }
    );
  },
  getRNICAAssessment: (assessmentId) => getRnicaAssessment(assessmentId),
  getRNICAAssessmentByPatient: (patientId, assessmentSubtype = undefined) =>
    assessmentSubtype
      ? getRnicaAssessmentByPatientType(patientId, { assessmentSubtype })
      : getRnicaAssessmentByPatient(patientId),
  updateRNICAAssessment: (assessmentId, formData, fieldProvenance) =>
    updateRnicaAssessmentOffline(assessmentId, formData, fieldProvenance),
  lockRNICAAssessment: (assessmentId) => lockRnicaAssessment(assessmentId),
  deleteRNICAAssessment: (assessmentId) => deleteRnicaAssessment(assessmentId),
  getRNICAIntelligence: (assessmentId) =>
    assessmentId ? getRnicaIntelligence(assessmentId) : null,
};


// ════════════════════════════════════════════════════════════════
// 4. VALIDATION
// ════════════════════════════════════════════════════════════════

export function validateRNICA(formData, mode = "ica", assessmentType = undefined) {
  const errors = {};
  const warnings = {};
  // Owner directive (GI SFV CMS Compliance Correction, includeHopeRequirements
  // defect review): this must use the SAME qualifying-HOPE-timepoint formula
  // as the render path (isQualifyingHopeTimepoint, RNICA.jsx ~line 18054),
  // not a standalone mode==="ongoing" check. A generic "ongoing" mode covers
  // both genuine HUV1/HUV2 Update visits (which DO require HOPE fields) and
  // non-HOPE Recertification visits (which do not) -- both call sites
  // already pass assessmentType; it was previously silently ignored here.
  const includeHopeRequirements =
    mode === "ica" || (mode === "ongoing" && assessmentType === "update");
  const requireAdmissionOrders = mode === "ica";

  // Demographics ? required fields
  if (!formData.demographics.firstName) errors["demographics.firstName"] = "First name is required";
  if (!formData.demographics.lastName) errors["demographics.lastName"] = "Last name is required";
  if (!formData.demographics.dob) errors["demographics.dob"] = "Date of birth is required";
  if (!formData.demographics.gender) errors["demographics.gender"] = "Gender is required";

  if (includeHopeRequirements) {
    // HOPE items ? A1110 Language
    if (!formData.demographics.preferredLanguage) {
      warnings["demographics.preferredLanguage"] = "HOPE A1110: Preferred language required";
    }
    // A1005 Ethnicity
    if (formData.demographics.ethnicity.length === 0) {
      warnings["demographics.ethnicity"] = "HOPE A1005: Ethnicity required";
    }
    // A1010 Race
    if (formData.demographics.race.length === 0) {
      warnings["demographics.race"] = "HOPE A1010: Race required";
    }

    // Advanced Care Planning — HOPE required
    if (!formData.demographics.advancedCarePlanning.cprPreferenceAskedStatus) {
      errors["demographics.advancedCarePlanning.cprPreferenceAskedStatus"] = "F2000: Was patient/responsible party asked about CPR preference? is required";
    }
    // [OWNER DIRECTIVE -- "ACP Review -- Code Status Requirement
    // Validation", 2026-10-22] Documented rule: Code Status is REQUIRED
    // unconditionally on every qualifying HOPE timepoint, regardless of
    // what `cprPreferenceAskedStatus` ("Asked About CPR") says --
    // because a patient's resuscitation status must always be on record
    // somewhere, independent of whether THIS visit is the one that
    // discussed it. This single required check already covers all four
    // scenarios without a separate branch per scenario:
    //   - Existing code status (carried forward from a prior visit/
    //     physician order/POLST): satisfies the check as-is -- no new
    //     discussion is forced just because one occurred previously.
    //   - New discussion this visit (askedStatus = "Yes, and discussion
    //     occurred"): the clinician selects the real resulting status
    //     (Full Code / DNR / Undecided).
    //   - No discussion this visit (askedStatus = "No"): a Code Status
    //     must still be on record -- use "Unable to Determine" if
    //     genuinely unknown rather than leaving the field blank.
    //   - Unable to determine (askedStatus = "Yes, but refused or
    //     unable to discuss"): "Unable to Determine" is itself a valid,
    //     always-available Code Status option -- it is never blocked by
    //     this requirement.
    if (!formData.demographics.advancedCarePlanning.codeStatus) {
      errors["demographics.advancedCarePlanning.codeStatus"] = "Code status is required";
    }
    if (!formData.demographics.advancedCarePlanning.lifeSustainingAskedStatus) {
      errors["demographics.advancedCarePlanning.lifeSustainingAskedStatus"] = "F2100: Was patient/responsible party asked about other life-sustaining treatments? is required";
    }
    if (!formData.demographics.advancedCarePlanning.lifeSustainingTreatmentPreference) {
      errors["demographics.advancedCarePlanning.lifeSustainingTreatmentPreference"] = "Life-sustaining treatment preference required";
    }
    if (!formData.demographics.advancedCarePlanning.hospitalizationAskedStatus) {
      errors["demographics.advancedCarePlanning.hospitalizationAskedStatus"] = "F2200: Was patient/responsible party asked about hospitalization preference? is required";
    }
    if (!formData.demographics.advancedCarePlanning.hospitalizationPreference) {
      errors["demographics.advancedCarePlanning.hospitalizationPreference"] = "Hospitalization preference required";
    }
  }

  if (!pcgIsAssessed(formData.demographics.pcg)) {
    warnings["demographics.pcg.assessed"] = "Primary Caregiver status not yet assessed this visit (Yes/No unanswered)";
  }

  // CDPH Gap #2 ? Caregiver capacity and readiness evaluation (skip entirely for No-PCG/facility patients).
  // [OWNER DIRECTIVE "Caregiver & Support Consolidation", 2026-10-23] Four
  // overlapping warnings (willingness, med-admin ability, willingness score,
  // capability score) are now two: the single authoritative Caregiver
  // Capacity field and the single authoritative Caregiver Readiness field.
  if (!formData.demographics.pcg.noPcg) {
    if (!formData.demographics.pcg.caregiverEvaluation?.physicalAbility) {
      warnings["demographics.pcg.caregiverEvaluation.physicalAbility"] = "CDPH: Caregiver capacity required";
    }
    if (!formData.demographics.pcg.caregiverEvaluation?.emotionalReadiness) {
      warnings["demographics.pcg.caregiverEvaluation.emotionalReadiness"] = "CDPH: Caregiver readiness required";
    }
  }

  if (includeHopeRequirements) {
    // Pain ? HOPE J0900, J0915
    if (!formData.pain.screenedForPain) {
      errors["pain.screenedForPain"] = "J0900.A: Was the patient screened for pain? is required";
    }
    if (formData.pain.screenedForPain === "1" && !formData.pain.painSeverityCategory) {
      errors["pain.painSeverityCategory"] = "J0900.C: Patient's pain severity is required when screened for pain";
    }
    if (formData.pain.screenedForPain === "1" && !formData.pain.standardizedPainToolType) {
      errors["pain.standardizedPainToolType"] = "J0900.D: Type of standardized pain tool used is required when screened for pain";
    }
    if (!formData.pain.verbalizesPain) {
      warnings["pain.verbalizesPain"] = "Pain verbalization status required to select pain scale";
    }
    if (!formData.pain.neuropathicPain) {
      errors["pain.neuropathicPain"] = "J0915: Does the patient have neuropathic pain? is required";
    }

    // Symptom Impact ? J2051 A-H (all 8 required)
    const siFields = ["pain","shortnessOfBreath","anxiety","nausea","vomiting","diarrhea","constipation","agitation"];
    siFields.forEach((f, i) => {
      if (!formData.symptomImpact[f]) {
        warnings[`symptomImpact.${f}`] = `HOPE J2051${String.fromCharCode(65 + i)}: ${f} score required`;
      }
    });

    // PRODUCT OWNER CORRECTION (repeated directive -- do not reintroduce
    // "Not at all"/"Not applicable") supersedes the prior Acceptance
    // Test 5 "Not applicable" contradiction check immediately below this
    // comment: SFV/anxietyImpact/agitationImpact no longer offer a "Not
    // applicable" response at all (see the field definitions in
    // SECTION_CONFIGS.neurological), so that contradiction can no longer
    // occur and the dedicated warning has been removed rather than left
    // dead.

    // SFV -- J2052A/C: an SFV is required whenever any J2051 item is
    // Moderate (2) or Severe (3). HOPE J2052C ownership fix (issue #146):
    // the reason SFV was not completed is NOT knowable at the time this
    // triggering RN ICA/HUV assessment is completed (the SFV attempt
    // hasn't happened yet) and is captured/validated authoritatively on
    // the SFV attempt visit instead (VisitNotes.jsx
    // ::SymptomFollowUpVisitSection). This assessment must never block
    // signing on a value the clinician cannot yet truthfully know.

    // Diagnoses ? I0010
    if (!formData.diagnoses.primaryDiagnosis.icd10) {
      errors["diagnoses.primaryDiagnosis"] = "HOPE I0010: Primary diagnosis ICD-10 required";
    }
    if (!formData.diagnoses.primaryDiagnosis.hopeDiagnosisCategory) {
      errors["diagnoses.primaryDiagnosis.hopeDiagnosisCategory"] = "HOPE I0010: Principal diagnosis category required";
    }

    // Performance Status ? M1190
    if (!formData.performanceStatus.pps && !formData.performanceStatus.kps) {
      warnings["performanceStatus"] = "HOPE M1190: At least PPS or KPS required";
    }

    // PRODUCT OWNER DECISION (2026-10-12) "SNS Cognitive Screen Removal
    // from Neuro Workflow" -- this warning previously required
    // `cognitiveScreen.repetition`, but that field's card is no longer
    // rendered anywhere in the Neurological workflow (see
    // `NeurologicalPanel.jsx`), so the warning could never be resolved by
    // any UI action. SNS Cognitive Screen was already confirmed not
    // CMS/HOPE/eligibility/RNICA-completion/narrative/POC required (see
    // `computeSnsCognitiveScreen` and the removed-card history above), so
    // this is not a HOPE/CMS requirement being dropped -- only an
    // internal, non-required warning that no longer has a reachable
    // trigger. Already-entered historical data and the calculation
    // function are untouched.

    // Imminent Death ? J0050
    if (!formData.imminentDeath.appearsThreeDaysOrLess) {
      warnings["imminentDeath.appearsThreeDaysOrLess"] = "HOPE J0050: Prognosis assessment required";
    }
  }

  // Skin ? Braden -- total is now system-derived; "Unable to assess"
  // (with a required reason) is an accepted terminal state, not a
  // missing-total warning. See PRODUCT OWNER DIRECTIVE (2026-11-22)
  // "RNICA-ONLY ADMISSION WORKFLOW" Section C.
  if (!formData.skin.braden.unableToAssess && !formData.skin.braden.total) {
    warnings["skin.braden.total"] = "Braden Scale total required";
  }
  if (formData.skin.braden.unableToAssess && !formData.skin.braden.unableToAssessReason) {
    warnings["skin.braden.unableToAssessReason"] = "Reason required when Braden cannot be assessed";
  }

  // Skin ? "Unable to Assess" (Section 7A) required sub-fields.
  if (formData.skin.skinConditionsPresent === "Unable to Assess") {
    if (!formData.skin.skinUnableToAssessReason) {
      warnings["skin.skinUnableToAssessReason"] = "Reason assessment could not be completed is required";
    }
    if (!formData.skin.skinImmediateConcern) {
      warnings["skin.skinImmediateConcern"] = "Immediate concern identified must be answered";
    }
    if (!formData.skin.skinFollowUpNeeded) {
      warnings["skin.skinFollowUpNeeded"] = "Follow-up or referral needed must be answered";
    }
  }

  // PRODUCT OWNER CORRECTION (2026-10-19) "Stop Mixing Clinical
  // Documentation With System Validation Logic" -- Prevention Gap
  // Identified / Immediate Action Required / Plan-of-Care Review
  // Required are system interpretations of what the RN already
  // documented (current prevention measures + pressure-injury risk/
  // presence), not clinical findings. The RN is no longer asked to
  // answer them, so no Coverage warning is raised for them; see
  // `deriveSkinPreventionSystemFlags` (computed inside
  // computeSkinDocumentationCoverage, Documentation Coverage/Validation
  // Layer only).

  // Psychosocial ? Suicide/self-harm safety documentation (CDPH: complete, accurate documentation required)
  if (formData.psychosocial.referralIndicators?.includes("Suicide/self-harm risk indicated") && !formData.psychosocial.notes?.trim()) {
    warnings["psychosocial.notes"] = "Safety: Suicide/self-harm risk indicated — document safety assessment/plan in Notes";
  }

  // SECTION 10 — Clinical Narrative & Disease Trajectory. The frozen
  // master map does not cite a HOPE code for this narrative (unlike the
  // hard-blocking Diagnoses/Pain/etc. items above), so this is a soft
  // completion warning rather than a hard error — but it applies equally
  // whether the narrative text was typed manually or built via "Build
  // Draft from Documented Findings," per the rule that a manually
  // entered narrative is just as valid as a generated one.
  if (formData.diagnoses.clinicalNarrative?.trim() && formData.diagnoses.clinicalNarrativeReviewed !== true) {
    warnings["diagnoses.clinicalNarrativeReviewed"] = "Clinical narrative documented but not yet reviewed — confirm review before finalizing (Section 10)";
  }

  // Admissions Order ? Level of Care required
  if (requireAdmissionOrders && !formData.admissionsOrder.levelOfCare.level) {
    errors["admissionsOrder.levelOfCare"] = "Level of Care is required for admission";
  }

  // Admissions Order ? T.O. Verification
  if (requireAdmissionOrders && !formData.admissionsOrder.toVerification.verbalOrderReadBack) {
    errors["admissionsOrder.toVerification"] = "Verbal order read-back verification required";
  }

  // Finalization ? signature
  if (!formData.finalization.clinicalNarrative) {
    errors["finalization.clinicalNarrative"] = "Clinical narrative is required before attestation";
  }
  if (!formData.finalization.clinicianSignature) {
    errors["finalization.clinicianSignature"] = "Clinician signature required";
  }

  // SECTION 12 — attestation. Previously present in the UI/INITIAL_FORM
  // but never enforced; the assessment must not be lockable without an
  // explicit clinician attestation that it is complete and accurate.
  if (formData.finalization.signatureCertification !== true) {
    errors["finalization.signatureCertification"] = "Signature certification (attestation) is required before locking";
  }

  // PRODUCT OWNER DIRECTIVE "Ambulation Status Safety Validation" (MSK
  // only) -- Ambulation Status is treated as a safety-critical Mobility
  // anchor (see "SNS Global Clinical Safety Rule"): it is the ONLY
  // Musculoskeletal field that hard-blocks Lock. This is an ERROR (not a
  // warning), and deliberately reuses `isMskMobilityComplete` -- the same
  // completeness predicate the `mobility` Documentation Coverage item's
  // `check` calls -- so Coverage's amber/green state and this Lock gate
  // can never disagree. No other MSK field, and no other Body System, is
  // touched by this directive.
  if (!isMskMobilityComplete(formData.musculoskeletal || {})) {
    errors["musculoskeletal.ambulationStatus"] = "Ambulation Status must be completed before this assessment can be finalized.";
  }

  // PRODUCT OWNER DIRECTIVE "Musculoskeletal Final Safety-State
  // Correction" -- "Unable to Tolerate Repositioning" is a documented
  // positive safety/comfort finding, distinct from the unresolved-field
  // check above. Hard-blocks Lock (no "Defer to Last" bypass exists for
  // this field, unlike Ambulation Status) until Immediate Response is
  // documented. Deliberately reuses `isMskRepositioningResponseComplete`
  // -- the same predicate the "Safety Response" Documentation Coverage
  // item's `check` calls -- so Coverage and this Lock gate can never
  // disagree. Notes alone do not satisfy this requirement; only the
  // structured Immediate Response field does.
  if (!isMskRepositioningResponseComplete(formData.musculoskeletal || {})) {
    errors["musculoskeletal.repositioningImmediateResponse"] = "Document the immediate response to the patient's inability to tolerate repositioning before finalizing.";
  }

  // PRODUCT OWNER DIRECTIVE "RNICA Neurological-MSK-Swallowing
  // Integration" -- same safety-response pattern as Repositioning
  // Immediate Response above, applied to Nutrition's Aspiration Concern:
  // a documented "Yes" (active concern) hard-blocks Lock until a
  // structured Response is selected. Deliberately reuses
  // `isNutritionAspirationConcernResponseComplete` -- the same predicate
  // the "Aspiration Concern" Documentation Coverage item's `check` calls.
  if (!isNutritionAspirationConcernResponseComplete(formData.nutrition || {})) {
    errors["nutrition.aspirationConcernResponse"] = "Document the response to the patient's aspiration concern before finalizing.";
  }

  // Section 14 "Finalization" -- when Neuro's Motor Deficit Present is
  // directly "Yes", the cross-system review (MSK Physical Motor
  // Limitation, Speech/Language, Swallowing/Dysphagia) must be completed
  // before Lock -- the same three completeness predicates the "Motor
  // Deficit Follow-Up" panel and each owning section's own Documentation
  // Coverage item already use, so Coverage, the follow-up panel, and this
  // Lock gate can never disagree. Mobility and Skin/Pressure Risk remain
  // review reminders only (not hard-blocked) -- they are not new
  // concepts introduced by Motor Deficit and already carry their own,
  // independent completion rules (or none) elsewhere.
  if (formData.neurological?.motorDeficitPresent === "Yes") {
    if (!isMskPhysicalMotorLimitationComplete(formData.musculoskeletal || {})) {
      errors["musculoskeletal.physicalMotorLimitationPresent"] = "Document the Musculoskeletal Physical Motor Limitation before finalizing a Motor Deficit finding.";
    }
    if (!isNeuroSpeechLanguageComplete(formData.neurological || {})) {
      errors["neurological.speechLanguageImpairmentPresent"] = "Document Speech / Language Impairment before finalizing a Motor Deficit finding.";
    }
    if (!isNutritionDysphagiaComplete(formData.nutrition || {})) {
      errors["nutrition.dysphagiaPresent"] = "Document Dysphagia before finalizing a Motor Deficit finding.";
    }
  }

  // PRODUCT OWNER DECISION (2026-11-29) "Fall Risk Assessment -- Morse
  // PRODUCT OWNER DIRECTIVE (2026-12-01) "Make Safety & Clinical Risk One
  // Assessment" sections 12-13 -- RNICA finalization creates exactly ONE
  // validation item for Safety (not four), reusing the same
  // `summarizeSafetyAssessment` predicate the unified wizard and the main
  // Overview card use, so Lock, the Overview badge, and the wizard step
  // indicators can never disagree. The Lock gate checks only whether
  // every part is complete-or-confirmed-Not-Applicable
  // (`allPartsComplete`) -- independent of whether the RN has also
  // clicked the Review step's "Complete Safety Assessment" submission --
  // so Lock is never blocked by a redundant UI click once every question
  // has in fact been answered.
  if (!summarizeSafetyAssessment(formData.safety || {}, formData).allPartsComplete) {
   errors["safety.assessment"] = "Complete the Safety & Clinical Risk Assessment (Environmental Safety, Morse Fall Scale, Oxygen Safety, and Disaster Triage) before finalizing.";
  }

  return { errors, warnings, isValid: Object.keys(errors).length === 0 };
}

// Structured Findings application layer — human-readable "destination
// field(s)" description for a concept, e.g. "cardiovascular.chfPresent" or
// "wounds[].location" — used only for RN-facing display in the Structured
// Findings review panel, never to derive the actual write logic (that
// still lives entirely in applyStructuredFindings.js against the same
// CONCEPT_REGISTRY).
function describeStructuredFindingDestinations(conceptCode) {
  const concept = CONCEPT_REGISTRY[conceptCode];
  if (!concept) return conceptCode;
  const writes = concept.writes || [];
  if (writes.length === 0 && concept.valueSlot) {
    return `${concept.section}.${concept.valueSlot.path}`;
  }
  return writes
    .map((w) => `${w.section || concept.section}.${w.path}`)
    .join(", ");
}


// ════════════════════════════════════════════════════════════════
// 5. HELPER COMPONENTS
// ════════════════════════════════════════════════════════════════


// Tag components
function HopeTag({ code }) {
  // OWNER DIRECTIVE (2026-10-29) "GI SFV CMS Compliance Correction" --
  // was `mode === "ongoing"`, which hid this tag during a genuine HOPE
  // Update Visit (HUV1/HUV2, assessmentType "update") exactly the same as
  // a non-HOPE Recertification (assessmentType "recert"). HOPE J-item
  // tags apply throughout the first 30 days of service (Admission + HUV1
  // + HUV2), not only on the Admission assessment.
  const isQualifyingHopeTimepoint = useContext(QualifyingHopeTimepointContext);
  const { mode: themeMode } = useThemeMode();
  const COLORS = useMemo(() => getRnicaColors(themeMode), [themeMode]);
  const styles = useMemo(() => getRnicaStyles(COLORS), [COLORS]);
  if (!isQualifyingHopeTimepoint) return null;
  return <span style={styles.hopeTag}>HOPE {code}</span>;
}
function SfvTag() {
  // OWNER DIRECTIVE (2026-10-29) "GI SFV CMS Compliance Correction" --
  // (1) same HUV1/HUV2-vs-Recert fix as HopeTag above; (2) "STATIC UI
  // LABEL" requirement: the static per-field tag means "this symptom
  // participates in HOPE SFV rules" -- it must never read as if an SFV
  // has already been activated, so the loud red "SFV Trigger" label is
  // replaced with the neutral "SFV" label plus an accessible tooltip.
  // Active-SFV-state badges remain a SEPARATE, differently-styled
  // element (the sfvStatus.required banners below), unaffected by this
  // change.
  const isQualifyingHopeTimepoint = useContext(QualifyingHopeTimepointContext);
  const { mode: themeMode } = useThemeMode();
  const COLORS = useMemo(() => getRnicaColors(themeMode), [themeMode]);
  const styles = useMemo(() => getRnicaStyles(COLORS), [COLORS]);
  if (!isQualifyingHopeTimepoint) return null;
  return (
    <span
      style={styles.sfvNeutralTag}
      title="Moderate or severe symptom impact during a HOPE Admission or HUV requires an in-person SFV within two calendar days."
    >
      SFV
    </span>
  );
}
function CmsTag({ label }) {
  const { mode: themeMode } = useThemeMode();
  const COLORS = useMemo(() => getRnicaColors(themeMode), [themeMode]);
  const styles = useMemo(() => getRnicaStyles(COLORS), [COLORS]);
  return <span style={styles.cmsTag}>CMS {label || "Required"}</span>;
}

// Form field components
// PRODUCT OWNER IMPLEMENTATION DIRECTIVE (2026-10-21) "GI Cleanup and
// HOPE N0520" Section 4 -- new optional `suffix` prop (e.g. Abdominal
// Girth's "cm") renders as a visible unit label *outside* the editable
// input -- never inside the stored value, never as a placeholder (a
// placeholder disappears once the nurse types a value and would make an
// empty field look "complete"). Every other field omits `suffix` and is
// unaffected.
function FormInput({ label, value, onChange, type = "text", placeholder, required, hopeCode, compact, suffix, ...rest }) {
  const { mode: themeMode } = useThemeMode();
  const COLORS = useMemo(() => getRnicaColors(themeMode), [themeMode]);
  const styles = useMemo(() => getRnicaStyles(COLORS), [COLORS]);
  const input = (
    <ShadcnInput
      type={type} value={value || ""}
      onChange={(e) => onChange(e.target.value)}
      placeholder={placeholder} {...rest}
    />
  );
  return (
    <div style={compact ? { ...styles.formGroup, marginBottom: 2 } : styles.formGroup}>
      <label style={styles.label}>
        {label} {required && <span style={{ color: COLORS.error }}>*</span>}
        {hopeCode && <> <HopeTag code={hopeCode} /></>}
      </label>
      {suffix ? (
        <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
          {input}
          <span style={{ fontSize: 11, color: COLORS.textMuted || "#6b7280" }}>{suffix}</span>
        </div>
      ) : input}
    </div>
  );
}

function FormTextarea({ label, value, onChange, placeholder, rows = 3, disabled, compact, autoGrow = false, collapsible = false }) {
  const { mode: themeMode } = useThemeMode();
  const COLORS = useMemo(() => getRnicaColors(themeMode), [themeMode]);
  const styles = useMemo(() => getRnicaStyles(COLORS), [COLORS]);
  // OWNER DIRECTIVE (2026-10-04) "Density Optimization Pass" item #7 --
  // "auto-growing textareas starting at 2 rows" for Additional Cognitive
  // Observations/Neurological Notes: a small `rows`-sized box by default
  // (keeps the collapsed-at-a-glance density win from the prior pass) that
  // grows with typed/charted content instead of relying on the browser's
  // native scrollbar once text exceeds the box. Opt-in via `autoGrow` so
  // every other FormTextarea call site (dozens, across every section)
  // keeps its exact current fixed-height behavior unchanged.
  const taRef = useRef(null);
  const resize = useCallback(() => {
    const el = taRef.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = `${el.scrollHeight}px`;
  }, []);
  useEffect(() => {
    if (autoGrow) resize();
  }, [autoGrow, value, resize]);
  // OWNER DIRECTIVE (2026-10-13) "SNS Global Body System Framework --
  // Horizontal Density" -- "Empty note fields shall collapse" / "the goal
  // is fewer scrolls, not smaller text". Mirrors the pattern already
  // shipped in RespiratoryPanel.tsx's Respiratory Notes field
  // (`rows={focused || !!value ? 4 : 1}`): a single-line collapsed box
  // when empty and unfocused, expanding to the field's normal `rows` once
  // it has content or the user is actively typing. Opt-in via
  // `collapsible` so every other FormTextarea call site keeps its exact
  // current height behavior unchanged -- only fields explicitly marked
  // `collapsible: true` are affected.
  const [focused, setFocused] = useState(false);
  const effectiveRows = collapsible && !focused && !value ? 1 : rows;
  return (
    <div style={compact ? { ...styles.formGroup, marginBottom: 2 } : styles.formGroup}>
      <label style={styles.label}>{label}</label>
      <ShadcnTextarea
        ref={autoGrow ? taRef : undefined}
        style={autoGrow ? { minHeight: effectiveRows * 24, height: effectiveRows * 24, overflow: "hidden", resize: "none" } : { minHeight: effectiveRows * 24 }}
        value={value || ""}
        onChange={(e) => { onChange(e.target.value); if (autoGrow) resize(); }}
        onFocus={collapsible ? () => setFocused(true) : undefined}
        onBlur={collapsible ? () => setFocused(false) : undefined}
        placeholder={placeholder} disabled={disabled}
      />
    </div>
  );
}

// Structured-charting alternative to a pure narrative textarea: tap a
// preset phrase to add/remove it from the same underlying string field
// (semicolon-joined), instead of free typing. Same path/data type as a
// plain textarea -- no schema change, no new field -- just a faster
// click-to-chart entry path. The textarea stays available underneath for
// anything a preset doesn't cover.
function FormQuickPickTextarea({ label, value, onChange, presets = [], placeholder, rows = 2, compact }) {
  const { mode: themeMode } = useThemeMode();
  const COLORS = useMemo(() => getRnicaColors(themeMode), [themeMode]);
  const styles = useMemo(() => getRnicaStyles(COLORS), [COLORS]);
  const parts = (value || "").split(";").map((s) => s.trim()).filter(Boolean);
  const togglePreset = (preset) => {
    const has = parts.includes(preset);
    const next = has ? parts.filter((p) => p !== preset) : [...parts, preset];
    onChange(next.join("; "));
  };
  return (
    <div style={compact ? { ...styles.formGroup, marginBottom: 2 } : styles.formGroup}>
      <label style={styles.label}>{label}</label>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginBottom: 6 }}>
        {presets.map((preset) => {
          const selected = parts.includes(preset);
          return (
            <button
              key={preset}
              type="button"
              onClick={() => togglePreset(preset)}
              style={{
                borderRadius: 999,
                border: selected ? `1px solid ${COLORS.teal}` : `1px solid ${COLORS.border}`,
                background: selected ? COLORS.teal : "transparent",
                // Bug fix (Pain Sheet UI polish pass): COLORS.text does not
                // exist in the getRnicaColors token map (only COLORS.dark
                // does), so this silently fell back to an inherited/near-
                // black color in dark mode -- e.g. "Effect on Function or
                // Quality of Life" presets reading dark-on-dark. COLORS.dark
                // is the correct legible primary-text token (same one the
                // adjacent pillGroup fields render with).
                color: selected ? "#fff" : COLORS.dark,
                fontSize: 11,
                fontWeight: 700,
                padding: "4px 10px",
                cursor: "pointer",
              }}
            >
              {preset}
            </button>
          );
        })}
      </div>
      <ShadcnTextarea
        style={{ minHeight: rows * 24 }} value={value || ""}
        onChange={(e) => onChange(e.target.value)} placeholder={placeholder || "Add detail not covered by the presets above (optional)"}
      />
    </div>
  );
}

// Sentinel used only inside FormSelect's own Radix <Select> -- Radix
// forbids an empty-string SelectItem value, so this internal-only
// placeholder stands in for "no selection" in the DOM/Radix layer. It is
// translated back to "" before `onChange`/`value` ever leave FormSelect,
// so every consumer (stored data, Coverage checks, legacy-value
// guardrail, etc.) still only ever sees the real "" / option-string
// value it always did.
const RNICA_SELECT_BLANK_SENTINEL = "__rnica_select_blank__";

function FormSelect({ label, value, onChange, options, required, hopeCode, disabled, compact }) {
  const { mode: themeMode } = useThemeMode();
  const COLORS = useMemo(() => getRnicaColors(themeMode), [themeMode]);
  const styles = useMemo(() => getRnicaStyles(COLORS), [COLORS]);
  // Same guardrail as FormSegmented (see its comment above) -- converting
  // a field from free text/a retired option to a narrower controlled
  // list must never hide or discard a value already on a patient's
  // record. When the stored value doesn't match any current option,
  // show it as a read-only review chip instead of silently rendering
  // the select as empty; the stored value itself is untouched.
  const hasLegacyValue = Boolean(value) && !options.some((opt) => (typeof opt === "string" ? opt : opt.value) === value);
  return (
    <div style={compact ? { ...styles.formGroup, marginBottom: 2 } : styles.formGroup}>
      <label style={styles.label}>
        {label} {required && <span style={{ color: COLORS.error }}>*</span>}
        {hopeCode && <> <HopeTag code={hopeCode} /></>}
      </label>
      <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
        <div style={{ flex: 1 }}>
          {/* PRODUCT OWNER DEFECT (2026-10-15) "Catheter Type Is Not
              Reversible" -- follow-up report: an external "✕ Clear"
              button placed outside Radix's <SelectContent> popover can
              be swallowed by the popover's own outside-click dismiss
              layer (first click only closes the open list; the button's
              own onClick doesn't reliably fire in the same click), so a
              nurse who opens the list and immediately clicks ✕ can see
              "nothing happen." Per the PO's own literal example ("Add a
              blank state. Example: Select Type...") the null state is
              now also a real, always-first item *inside* the dropdown
              list itself -- selecting it is a normal in-list selection
              with no outside-click race, exactly like choosing any other
              option. Radix forbids an empty-string SelectItem value, so
              a sentinel ("__rnica_select_blank__") is used internally and
              translated back to "" before `onChange` ever sees it -- the
              stored value/shape is unchanged (still "" = not answered,
              same as every other falsy-check in Coverage etc.). The
              external ✕ button is kept as a redundant single-click
              shortcut for when the list is already closed. */}
          <Select
            value={value || RNICA_SELECT_BLANK_SENTINEL}
            onValueChange={(v) => onChange(v === RNICA_SELECT_BLANK_SENTINEL ? "" : v)}
            disabled={disabled}
          >
            <SelectTrigger><SelectValue placeholder="— Select —" /></SelectTrigger>
            <SelectContent>
              <SelectItem value={RNICA_SELECT_BLANK_SENTINEL}>— Select —</SelectItem>
              {options.map((opt) => {
                const val = typeof opt === "string" ? opt : opt.value;
                const lbl = typeof opt === "string" ? opt : opt.label;
                return <SelectItem key={val} value={val}>{lbl}</SelectItem>;
              })}
            </SelectContent>
          </Select>
        </div>
        {Boolean(value) && !disabled && (
          <button
            type="button"
            onClick={() => onChange("")}
            title="Clear selection"
            aria-label={`Clear ${label}`}
            style={{
              flexShrink: 0,
              border: `1px solid ${COLORS.border}`,
              background: "transparent",
              color: COLORS.gray,
              borderRadius: 6,
              width: 26,
              height: 26,
              fontSize: 13,
              lineHeight: 1,
              cursor: "pointer",
            }}
          >
            ✕
          </button>
        )}
      </div>
      {hasLegacyValue && (
        <span
          title="This value was previously recorded but is no longer offered as an option. The stored value has not been changed."
          className="ml-1 inline-block rounded-full border border-dashed border-rnica-orange px-2 py-[2px] text-[10px] font-semibold leading-[1.6] text-rnica-orange whitespace-nowrap"
        >
          ⚠ Previously recorded: "{value}"
        </span>
      )}
    </div>
  );
}

function FormRadioGroup({ label, value, onChange, options, hopeCode, sfv }) {
  const { mode: themeMode } = useThemeMode();
  const COLORS = useMemo(() => getRnicaColors(themeMode), [themeMode]);
  const styles = useMemo(() => getRnicaStyles(COLORS), [COLORS]);
  // PRODUCT OWNER DECISION (2026-10-15) "Resolve Catheter Redundancy" --
  // same guardrail `FormSegmented`/`FormCheckboxGroup` already have: a
  // single-select option can be retired from the visible list (e.g. GU's
  // "Catheterized" folding into "Catheter Present" as the sole workflow
  // driver) without ever deleting or rewriting a patient's previously
  // stored value. When the stored value no longer matches any current
  // option, show a small review chip instead of silently rendering
  // "nothing selected" -- the raw value is untouched.
  const hasLegacyValue = Boolean(value) && !options.some((opt) => (typeof opt === "string" ? opt : opt.value) === value);
  return (
    <div style={styles.formGroup}>
      <label style={styles.label}>
        {label}
        {hopeCode && <> <HopeTag code={hopeCode} /></>}
        {sfv && <> <SfvTag /></>}
      </label>
      <RadioGroup style={styles.radioGroup} value={value ?? undefined} onValueChange={onChange}>
        {options.map((opt) => {
          const val = typeof opt === "string" ? opt : opt.value;
          const lbl = typeof opt === "string" ? opt : opt.label;
          return (
            <label key={val} style={styles.radioLabel}>
              <RadioGroupItem value={val} />
              {lbl}
            </label>
          );
        })}
      </RadioGroup>
      {hasLegacyValue && (
        <span
          title="This value was previously recorded but is no longer offered as an option. The stored value has not been changed."
          className="ml-1 inline-block rounded-full border border-dashed border-rnica-orange px-2 py-[2px] text-[10px] font-semibold leading-[1.6] text-rnica-orange whitespace-nowrap"
        >
          ⚠ Previously recorded: “{value}”
        </span>
      )}
    </div>
  );
}

// GitHub Directive (2026-09-28) Critical Finding #4 -- progressive
// disclosure for single-select fields whose full option list creates
// "too many choices displayed simultaneously." Renders two large primary
// buttons; only when the current/selected value falls outside
// `normalValues` does a second, compact detail row of the remaining
// options appear. Both tiers write to the SAME field path -- no new field,
// no option removed, so every existing stored value (including legacy
// detail strings) round-trips exactly as before.
function FormGatedRadio({ label, value, onChange, primaryOptions, normalValues, detailOptions, hopeCode }) {
  // Bounded Compatibility Increment Section 13 -- primaryOptions may now
  // contain {value,label} display-adapter entries (matching FormSegmented's
  // existing convention, e.g. Communication's stored "Normal" displaying as
  // "No Current Communication Concern"). Only VALUES drive the gating
  // logic below; stored data and detail-reveal behavior are unchanged.
  const primaryValues = primaryOptions.map((opt) => (typeof opt === "string" ? opt : opt.value));
  const isDetailValue = Boolean(value) && !primaryValues.includes(value) && !normalValues.includes(value);
  const primaryValue = isDetailValue ? primaryValues[1] : (normalValues.includes(value) ? primaryValues[0] : value);
  const showDetail = isDetailValue || primaryValue === primaryValues[1];
  return (
    <div>
      <FormSegmented label={label} value={primaryValue} onChange={onChange} options={primaryOptions} hopeCode={hopeCode} />
      {showDetail && (
        <div style={{ marginTop: 4, marginLeft: 12, paddingLeft: 8, borderLeft: "2px solid var(--rnica-border, #d0d5dd)" }}>
          <FormSegmented label={`${label} — Detail`} value={isDetailValue ? value : undefined} onChange={onChange} options={detailOptions} />
        </div>
      )}
    </div>
  );
}

// Tri-state control for clinical "present/absent" findings that must not
// collapse "never assessed" and "assessed as negative" into the same value
// (a plain unchecked checkbox can't be told apart from a skipped field).
// Backward-compatible with legacy boolean data: true -> "Yes", false/""/null -> "" (Not Assessed).
function normalizeTriState(value) {
  if (value === true) return "Yes";
  if (value === "Yes" || value === "No") return value;
  return "";
}

// PRODUCT OWNER DIRECTIVE (2026-11-10) "CORRECT THE GI BOWEL DATA MODEL" --
// the legacy single-select `gastrointestinal.bowelStatus` field
// (Regular/Irregular/Impaction/Continent/Incontinent/Bowel-bladder program)
// forced 4 independent clinical concepts into one mutually-exclusive enum
// (a patient can be BOTH Irregular AND Incontinent AND on a bowel program at
// the same time -- the old field could only ever record one). Split into 4
// new canonical fields (Bowel Pattern, Fecal Impaction, Bowel Continence --
// reusing the pre-existing but previously-unrendered `continence` path per
// the repo's reuse-before-create rule, Bowel Program). New assessments are
// written only to the new fields (the "Bowel Status" control has been
// removed from SECTION_CONFIGS below); `bowelStatus` itself is left in
// INITIAL_FORM/state (not deleted) purely for backward-compatible reads of
// already-finalized historical charts. Every consumer that used to read
// `bowelStatus` directly (LCD continence-evidence scoring, narrative
// builder, Documentation Coverage) now goes through these adapters: new
// field value wins if present, else derive from the legacy value, else "".
// Forward-only -- never writes back to `bowelStatus`.
function getEffectiveBowelPattern(gi) {
  const next = gi?.bowelPattern || "";
  if (next) return next;
  const legacy = gi?.bowelStatus || "";
  if (legacy === "Regular") return "Regular";
  if (legacy === "Irregular") return "Irregular";
  return "";
}
function getEffectiveFecalImpaction(gi) {
  const next = gi?.fecalImpaction || "";
  if (next) return next;
  return gi?.bowelStatus === "Impaction" ? "Confirmed" : "";
}
function getEffectiveBowelContinence(gi) {
  const next = gi?.continence || "";
  if (next) return next;
  const legacy = gi?.bowelStatus || "";
  if (legacy === "Continent") return "Continent";
  if (legacy === "Incontinent") return "Incontinent";
  return "";
}
function getEffectiveBowelProgram(gi) {
  const next = gi?.bowelProgram || "";
  if (next) return next;
  // Owner-provided migration mapping: legacy "Bowel/bladder program" means a
  // program was active -- it must NOT be read as evidence of continence
  // status (continence and program are independent concepts).
  return gi?.bowelStatus === "Bowel/bladder program" ? "Bowel Program Active" : "";
}
// PRODUCT OWNER CORRECTION (2026-10-21) "N0520 Reason -- One Fact, One
// Location" -- the multi-select checkbox reason list (plus a separate
// "Other Reason" free-text field) let the same fact be documented in up
// to three places alongside GI Notes. Replaced with a single-select
// dropdown (`bowelRegimenReason`); same forward-only adapter pattern as
// getEffectiveBowelPattern/etc. above -- new field value wins if
// present, else fall back to the first non-"Other" value a nurse
// selected under the retired multi-select `bowelRegimenReasons` array
// (historical data only; never written to by new assessments).
function getEffectiveBowelRegimenReason(gi) {
  const next = gi?.bowelRegimenReason || "";
  if (next) return next;
  const legacy = (gi?.bowelRegimenReasons || []).filter((r) => r !== "Other" && r !== BOWEL_REGIMEN_OTHER_REASON);
  return legacy[0] || "";
}

// PRODUCT OWNER DIRECTIVE (2026-10-14) "GI Clinical Review -- Abdominal
// Assessment Regression" -- the legacy single-select `gastrointestinal.
// abdomen` field (Soft/Firm/Tympanic/Distended/Tender/Nontender/Rigid)
// forced 3 independent clinical dimensions (consistency, tenderness,
// appearance/distention) into one mutually-exclusive enum, making
// legitimate combinations (e.g. "Soft + Distended + Tender") impossible to
// document. Split into 3 new canonical fields along those axes. New
// assessments are written only to the new fields; `abdomen` itself is left
// in INITIAL_FORM/state (not deleted) purely for backward-compatible reads
// of already-finalized historical charts. Same forward-only adapter
// pattern as getEffectiveBowelPattern/etc. above: new field value wins if
// present, else derive from the legacy value, else "". Never writes back
// to `abdomen`.
function getEffectiveAbdomenConsistency(gi) {
  const next = gi?.abdomenConsistency || "";
  if (next) return next;
  const legacy = gi?.abdomen || "";
  if (legacy === "Soft" || legacy === "Firm" || legacy === "Rigid") return legacy;
  return "";
}
function getEffectiveAbdomenTenderness(gi) {
  const next = gi?.abdomenTenderness || "";
  if (next) return next;
  const legacy = gi?.abdomen || "";
  if (legacy === "Tender" || legacy === "Nontender") return legacy;
  return "";
}
function getEffectiveAbdomenAppearance(gi) {
  const next = gi?.abdomenAppearance || "";
  if (next) return next;
  const legacy = gi?.abdomen || "";
  if (legacy === "Distended" || legacy === "Tympanic") return legacy;
  return "";
}

// Back-compat check for pre-existing PCG data saved before the explicit
// "assessed" flag was introduced: if the record already has a meaningful
// answer (facility-based no-PCG, or any populated PCG detail field), treat
// it as already assessed so legacy/finalized charts aren't retroactively
// flagged as incomplete — never rewrites the stored data itself.
function pcgIsAssessed(pcg) {
  if (!pcg) return false;
  if (pcg.assessed === true) return true;
  if (pcg.noPcg === true) return true;
  return Boolean(pcg.name || pcg.relationship || pcg.phone || pcg.anxietyLevel || pcg.caregiverEvaluation?.physicalAbility || pcg.caregiverEvaluation?.emotionalReadiness);
}

// [OWNER DIRECTIVE "Caregiver & Support Face Sheet Integration",
// 2026-10-23] RNICA assesses caregiver capability; it does not rebuild
// patient demographics. Caregiver contact info (name/relationship/
// phone) is suggested from whichever authoritative Face Sheet record
// already identifies a likely caregiver, most to least specific:
// the shared Primary Caregiver contact record (entered/maintained
// elsewhere and synced everywhere), then Responsible Party, then
// Decision Maker, then Emergency Contact (an ER contact is not
// guaranteed to be the caregiver, so it is the last-resort fallback).
// Returns null (no suggestion) when nothing on file has a name.
//
// [BUGFIX 2026-10-23] Some Face Sheet contact records (entered before
// RNICA's Relationship/Decision-Making Authority split existed) store a
// single combined string in their relationship field, e.g.
// "Son / Power of Attorney". Feeding that raw string into RNICA's
// Relationship field would recreate exactly the merged field the owner
// explicitly rejected. This helper recognizes a known authority term
// (Power of Attorney/POA, Healthcare Proxy, Legal Guardian, Conservator)
// appended after a separator and splits it out, so the suggestion always
// carries a clean relationship plus a separately identified authority.
const LEGACY_AUTHORITY_TERMS = [
  { re: /power of attorney|\bpoa\b/i, label: "Power of Attorney" },
  { re: /healthcare proxy/i, label: "Healthcare Proxy" },
  { re: /legal guardian/i, label: "Legal Guardian" },
  { re: /conservator/i, label: "Conservator" },
];
function splitLegacyRelationshipAuthority(rawRelationship) {
  const text = (rawRelationship || "").trim();
  if (!text) return { relationship: "", authority: "" };
  const term = LEGACY_AUTHORITY_TERMS.find((t) => t.re.test(text));
  if (!term) return { relationship: text, authority: "" };
  const remainder = text.replace(term.re, "").replace(/^[\s/,\-–]+|[\s/,\-–]+$/g, "").trim();
  return { relationship: remainder, authority: term.label };
}
// [BUGFIX 2026-10-23, cont.] The split above only prevents *new*
// suggestions from merging relationship+authority. Records saved before
// the split existed (or via the old suggestion logic) may already have
// the combined string sitting in the stored `pcg.relationship` field
// itself. Rather than silently rewriting saved chart data, use the same
// forward-only display adapter pattern as getEffectiveAbdomenConsistency
// above: derive a clean value for display only; the instant the RN edits
// either field directly, the typed value no longer matches the legacy
// combined pattern and these adapters pass it through unchanged.
function getEffectivePcgRelationship(pcg) {
  const stored = pcg?.relationship || "";
  if (pcg?.legalAuthority) return stored;
  return splitLegacyRelationshipAuthority(stored).relationship;
}
function getEffectivePcgLegalAuthority(pcg) {
  if (pcg?.legalAuthority) return pcg.legalAuthority;
  return splitLegacyRelationshipAuthority(pcg?.relationship).authority;
}
function getSuggestedCaregiverFromFacesheet(facesheetData) {
  const contacts = facesheetData?.contacts || {};
  const candidates = [
    { entry: contacts.primary_caregiver, source: "Face Sheet — Primary Caregiver" },
    { entry: contacts.responsible_party, source: "Face Sheet — Responsible Party" },
    { entry: contacts.decision_maker, source: "Face Sheet — Decision Maker" },
    { entry: contacts.emergency_contact, source: "Face Sheet — Emergency Contact" },
  ];
  const match = candidates.find((c) => c.entry?.name);
  if (!match) return null;
  const { relationship, authority } = splitLegacyRelationshipAuthority(match.entry.relationship);
  return { name: match.entry.name, relationship, authority, phone: match.entry.phone, source: match.source };
}

function FormTriState({ label, value, onChange, hopeCode }) {
  const { mode: themeMode } = useThemeMode();
  const COLORS = useMemo(() => getRnicaColors(themeMode), [themeMode]);
  const styles = useMemo(() => getRnicaStyles(COLORS), [COLORS]);
  const normalized = normalizeTriState(value);
  const options = [
    { value: "", label: "Not Assessed" },
    { value: "No", label: "No" },
    { value: "Yes", label: "Yes" },
  ];
  return (
    <div style={styles.formGroup}>
      <label style={styles.label}>
        {label}
        {hopeCode && <> <HopeTag code={hopeCode} /></>}
      </label>
      <RadioGroup style={styles.radioGroup} value={normalized || "unassessed"} onValueChange={(v) => onChange(v === "unassessed" ? "" : v)}>
        {options.map((opt) => (
          <label key={opt.value || "unassessed"} style={{
            ...styles.radioLabel,
            ...(opt.value === "" && normalized === "" ? { color: COLORS.gray, fontStyle: "italic" } : {}),
          }}>
            <RadioGroupItem value={opt.value || "unassessed"} />
            {opt.label}
          </label>
        ))}
      </RadioGroup>
    </div>
  );
}

function FormCheckboxGroup({ label, values = [], onChange, options, hopeCode }) {
  const { mode: themeMode } = useThemeMode();
  const COLORS = useMemo(() => getRnicaColors(themeMode), [themeMode]);
  const styles = useMemo(() => getRnicaStyles(COLORS), [COLORS]);
  const toggle = (val) => {
    const next = values.includes(val) ? values.filter((v) => v !== val) : [...values, val];
    onChange(next);
  };
  // GU urine-model-consolidation pass (2026-11) -- same guardrail
  // `FormSegmented` already has for a single-select option retired from
  // the visible list (e.g. "Pale"/"Odor" folded away when GU's two
  // parallel urine-characteristics option sets were merged into one):
  // a previously-checked value that no longer matches any current option
  // is never silently dropped from view. The raw stored array is
  // untouched either way (toggling a different, still-offered option
  // does not remove it) -- this only adds a read-only review chip so the
  // nurse/auditor can see it was charted.
  const legacyValues = (values || []).filter((v) => !options.some((opt) => (typeof opt === "string" ? opt : opt.value) === v));
  return (
    <div style={styles.formGroup}>
      <label style={styles.label}>
        {label}
        {hopeCode && <> <HopeTag code={hopeCode} /></>}
      </label>
      <div style={styles.checkboxGroup}>
        {options.map((opt) => {
          const val = typeof opt === "string" ? opt : opt.value;
          const lbl = typeof opt === "string" ? opt : opt.label;
          return (
            <label key={val} style={styles.checkboxLabel}>
              <Checkbox checked={values.includes(val)} onCheckedChange={() => toggle(val)} />
              <span>{lbl}</span>
            </label>
          );
        })}
      </div>
      {legacyValues.length > 0 && (
        <div style={{ marginTop: 4, display: "flex", flexWrap: "wrap", gap: 4 }}>
          {legacyValues.map((legacyValue) => (
            <span
              key={legacyValue}
              title="This value was previously recorded but is no longer offered as an option. The stored value has not been changed."
              className="inline-block rounded-full border border-dashed border-rnica-orange px-2 py-[2px] text-[10px] font-semibold leading-[1.6] text-rnica-orange whitespace-nowrap"
            >
              ⚠ Previously recorded: “{legacyValue}”
            </span>
          ))}
        </div>
      )}
    </div>
  );
}

// GitHub UI Directive (2026-09-28) -- compact segmented-control replacement
// for FormRadioGroup's larger circular-radio rows, opt-in only via
// `type: "segmented"` on a field config (FormRadioGroup itself is
// untouched and keeps rendering exactly as before everywhere it is still
// used, so no other Body System or assessment screen changes visually).
// Same single-value/onChange contract as FormRadioGroup -- no data shape
// change. Optional `aliases` lets a legacy/duplicate stored value (e.g.
// "Awake") render as an already-existing canonical option (e.g. "Alert")
// selected, without ever writing the alias again and without removing the
// legacy value from the option list or backend concept registry.
// Bug fix (2026-10-15) "not assessed cant be selected" -- see the
// FormSegmented ToggleGroup usage below for the full explanation. Module-
// level constant (not component-local) so its identity is stable across
// renders/components and it's trivially greppable as the one place this
// sentinel is defined.
const RNICA_EMPTY_SEGMENTED_VALUE = "__rnica_segmented_unset__";
function FormSegmented({ label, value, onChange, options, hopeCode, sfv, aliases, compact, hideLegacyBadge, disabled }) {
  const { mode: themeMode } = useThemeMode();
  const COLORS = useMemo(() => getRnicaColors(themeMode), [themeMode]);
  const styles = useMemo(() => getRnicaStyles(COLORS), [COLORS]);
  const displayValue = (aliases && aliases[value]) || value;
  // GitHub Directive (2026-09-28) Section 37/40 guardrail -- an option can
  // be retired from the visible control (e.g. duplicate concepts like
  // "Hearing aid" moving to Sensory Aids) without ever deleting a
  // patient's previously stored value. When the stored value no longer
  // matches any current option, show a small review chip instead of
  // silently rendering "nothing selected" -- the raw value is untouched.
  // PRODUCT OWNER CORRECTION (2026-11-16) "MSK Rehabilitation-Thinking
  // Removal" -- opt-in `hideLegacyBadge` lets one specific field config
  // suppress this chip entirely (SNS is not a production EMR; current
  // records are test data and this chip's "review this old value" framing
  // doesn't apply). Defaults to false so every other FormSegmented caller
  // across every other Body System keeps this guardrail exactly as-is --
  // only MSK's Weakness/Gait fields opt in, since those two fields are the
  // ones whose retired option (Paralysis/Unable) this directive named.
  const hasLegacyValue = !hideLegacyBadge && Boolean(displayValue) && !options.some((opt) => (typeof opt === "string" ? opt : opt.value) === displayValue);
  return (
    <div style={compact ? { ...styles.formGroup, marginBottom: 2 } : styles.formGroup}>
      <label style={styles.label}>
        {label}
        {hopeCode && <> <HopeTag code={hopeCode} /></>}
        {sfv && <> <SfvTag /></>}
      </label>
      {/* shadcn/ui ToggleGroup (Radix), type="single" -- compact mutually
          exclusive clinical-status chip row. Re-clicking the selected chip
          deselects it (Radix's native single-type behavior), preserving the
          existing "" unselected-default convention used throughout this
          file without any extra onClick interception.
          Bug fix (2026-10-15) "not assessed cant be selected" -- Radix's
          ToggleGroup treats an empty-string `value` as its own internal
          "nothing is selected" sentinel, not as a real selectable value.
          Every tri-state field in this file (segmentedTriState's "Not
          Assessed" / any other field whose blank/default option is
          literally "") passes `value=""` for that option, so Radix could
          never render that item as selected -- once a nurse picked "No"
          or "Yes", clicking back to "Not Assessed" visually did nothing
          (`data-state` stayed "off" on every chip, `onValueChange` never
          fired with "" because Radix's own click handler short-circuits
          on a falsy item value before it ever reaches our `onChange`).
          `RNICA_EMPTY_SEGMENTED_VALUE` is a non-empty sentinel used only
          for Radix's internal `value`/item-`value` matching -- translated
          back to the real "" the moment it leaves this component, so the
          stored field value contract (still "" for "unanswered") is
          completely unchanged for every existing chart. */}
      <ToggleGroup type="single" aria-label={label} disabled={disabled}
        value={(displayValue || "") === "" ? RNICA_EMPTY_SEGMENTED_VALUE : displayValue}
        onValueChange={(v) => onChange(!v || v === RNICA_EMPTY_SEGMENTED_VALUE ? "" : v)}>
        {options.map((opt) => {
          const val = typeof opt === "string" ? opt : opt.value;
          const lbl = typeof opt === "string" ? opt : opt.label;
          const toggleVal = val === "" ? RNICA_EMPTY_SEGMENTED_VALUE : val;
          return (
            <ToggleGroupItem key={toggleVal} value={toggleVal}>
              {lbl}
            </ToggleGroupItem>
          );
        })}
      </ToggleGroup>
      {hasLegacyValue && (
        <span
          title="This value was previously recorded but is no longer offered as an option. The stored value has not been changed."
          className="ml-1 inline-block rounded-full border border-dashed border-rnica-orange px-2 py-[2px] text-[10px] font-semibold leading-[1.6] text-rnica-orange whitespace-nowrap"
        >
          ⚠ Previously recorded: “{displayValue}”
        </span>
      )}
    </div>
  );
}

// Compact multi-select pill row, opt-in via `type: "pillGroup"`. Same
// array-value/onChange contract as FormCheckboxGroup (untouched, still
// used everywhere else) -- purely a denser visual for Body Systems.
function FormPillGroup({ label, values = [], onChange, options, hopeCode, compact }) {
  const { mode: themeMode } = useThemeMode();
  const COLORS = useMemo(() => getRnicaColors(themeMode), [themeMode]);
  const styles = useMemo(() => getRnicaStyles(COLORS), [COLORS]);
  // GU Review (2026-10-22) "Blood/Hematuria merge" -- same guardrail
  // `FormCheckboxGroup` already has for a multi-select option retired
  // from the visible list (e.g. GU's "Blood"/"Hematuria" folded into one
  // "Blood/Hematuria" option): a previously-checked value that no longer
  // matches any current option is never silently dropped from view. The
  // raw stored array is untouched either way -- this only adds a
  // read-only review chip so the nurse/auditor can see it was charted.
  const legacyValues = (values || []).filter((v) => !options.some((opt) => (typeof opt === "string" ? opt : opt.value) === v));
  return (
    <div style={compact ? { ...styles.formGroup, marginBottom: 2 } : styles.formGroup}>
      {/* PRODUCT OWNER DIRECTIVE (2026-10-21) "Neurological Design
          Review -- Redundant Labeling" -- a field's label row is only
          rendered when a label is actually supplied. Previously this
          <label> always rendered, so an empty/omitted label still took
          a line (and, for assistive tech, an empty accessible name).
          Fields that genuinely have no category label (e.g. "Symptoms /
          Demeanor" on Neuro's Cognitive/Behavioral card, now unlabeled
          because the pills are self-explanatory) skip it entirely.
          Every other current pillGroup usage still supplies a label, so
          this is additive -- no visible change anywhere else. */}
      {label && (
        <label style={styles.label}>
          {label}
          {hopeCode && <> <HopeTag code={hopeCode} /></>}
        </label>
      )}
      {/* shadcn/ui ToggleGroup (Radix), type="multiple" -- independent
          multi-select findings/interventions chip row. */}
      <ToggleGroup type="multiple" aria-label={label || undefined} value={values} onValueChange={(v) => onChange(v ?? [])}>
        {options.map((opt) => {
          const val = typeof opt === "string" ? opt : opt.value;
          const lbl = typeof opt === "string" ? opt : opt.label;
          return (
            <ToggleGroupItem key={val} value={val}>
              {lbl}
            </ToggleGroupItem>
          );
        })}
      </ToggleGroup>
      {legacyValues.length > 0 && (
        <div style={{ marginTop: 4, display: "flex", flexWrap: "wrap", gap: 4 }}>
          {legacyValues.map((legacyValue) => (
            <span
              key={legacyValue}
              title="This value was previously recorded but is no longer offered as an option. The stored value has not been changed."
              className="inline-block rounded-full border border-dashed border-rnica-orange px-2 py-[2px] text-[10px] font-semibold leading-[1.6] text-rnica-orange whitespace-nowrap"
            >
              ⚠ Previously recorded: “{legacyValue}”
            </span>
          ))}
        </div>
      )}
    </div>
  );
}


function FormCheckbox({ label, checked, onChange, disabled = false }) {
  const { mode: themeMode } = useThemeMode();
  const COLORS = useMemo(() => getRnicaColors(themeMode), [themeMode]);
  const styles = useMemo(() => getRnicaStyles(COLORS), [COLORS]);
  return (
    <label style={{ ...styles.checkboxLabel, ...styles.formGroup, opacity: disabled ? 0.55 : 1, cursor: disabled ? "not-allowed" : "pointer" }}>
      <Checkbox checked={checked || false} disabled={disabled} onCheckedChange={onChange} />
      <span style={{ fontSize: 13, fontWeight: 500 }}>{label}</span>
    </label>
  );
}

// GitHub UI Directive (2026-09-28) -- "checkbox should never be larger
// than the text it represents." Single yes/no findings (e.g. "Motor
// Deficit Present") no longer render as a large square Checkbox next to
// a separate label; they render as one compact toggle pill, same visual
// language/size as FormSegmented/FormPillGroup. Same boolean value/
// onChange(bool) contract as FormCheckbox -- no data shape change.
//
// Body System Visual Consistency Review (product-owner finding,
// "Cool Extremities / Varicose Veins / Pacemaker ... are all the same
// but Normal / Cyanotic / Mild / Moderate are a different color"):
// confirmed via live computed-style diagnostics that FormBooleanPill's
// unchecked background -- literal `"transparent"` -- renders fully
// see-through (rgba(0,0,0,0)), while FormSegmented/FormPillGroup's
// unchecked ToggleGroupItem chips render a solid `rgb(24,44,66)`
// (`var(--sns-cardSoft)`) because a global `.rnica-screen button` CSS
// rule overrides their `bg-transparent` utility class on specificity --
// an inline style like this one is never touched by that rule. Two
// different "unselected pill" visuals were therefore appearing side by
// side in the same card (e.g. Cardiovascular's boolean Devices pills vs.
// its categorical Skin Color/severity pills) with no clinical meaning
// behind the difference. Painting the same `var(--sns-cardSoft)` token
// here makes every unselected pill -- boolean or categorical -- render
// identically, matching the app-wide dominant chip color.
function FormBooleanPill({ label, checked, onChange, disabled = false }) {
  const { mode: themeMode } = useThemeMode();
  const COLORS = useMemo(() => getRnicaColors(themeMode), [themeMode]);
  const isChecked = Boolean(checked);
  return (
    <button
      type="button" aria-pressed={isChecked} disabled={disabled}
      className="rnica-segment-btn"
      onClick={() => onChange(!isChecked)}
      style={{
        padding: "2px 9px", fontSize: 11, lineHeight: 1.6, borderRadius: 999,
        cursor: disabled ? "not-allowed" : "pointer", opacity: disabled ? 0.55 : 1,
        border: `1px solid ${isChecked ? COLORS.teal : COLORS.border}`,
        background: isChecked ? COLORS.teal : "var(--sns-cardSoft)",
        color: isChecked ? COLORS.textOnTeal : COLORS.dark,
        fontWeight: isChecked ? 700 : 500, whiteSpace: "nowrap",
      }}
    >
      {label}
    </button>
  );
}

const LCD_AUTO_FACT_FIELDS = new Set([
  "pps",
  "kps",
  "nyha_class",
  "fast_stage_at_or_beyond_7a",
  "fast_stage",
  "adl_dependency_count",
  "ambulation_assistance_required",
  "dressing_assistance_required",
  "bathing_assistance_required",
  "incontinence_or_catheter_ostomy_dependency",
  "is_bedbound",
  "dysphagia",
  "oral_intake_decline",
  "weight_loss_percent_6_months",
  "weight_loss_lbs",
  "continued_weight_loss",
  "o2_sat_percent",
  "resting_tachycardia_gt_100",
]);

function normalizeLcdNumber(value) {
  if (value === null || value === undefined || value === "") return null;
  if (typeof value === "number") return Number.isFinite(value) ? value : null;
  const match = String(value).replace(/,/g, "").match(/-?\d+(\.\d+)?/);
  return match ? Number(match[0]) : null;
}

function normalizeFastStage(value) {
  return value ? String(value).trim().toLowerCase() : "";
}

function fastStageAtOrBeyond7a(value) {
  const order = {
    "1": 10, "2": 20, "3": 30, "4": 40, "5": 50,
    "6a": 61, "6b": 62, "6c": 63, "6d": 64, "6e": 65,
    "7a": 71, "7b": 72, "7c": 73, "7d": 74, "7e": 75, "7f": 76,
  };
  const key = normalizeFastStage(value);
  return key ? (order[key] || 0) >= order["7a"] : null;
}

function parseWeightLoss(value) {
  if (!value) return { lbs: null, percent: null };
  const num = normalizeLcdNumber(value);
  if (num === null) return { lbs: null, percent: null };
  if (String(value).includes("%")) return { lbs: null, percent: num };
  return { lbs: num, percent: null };
}

function normalizeYesNoUnknown(value) {
  if (value === true || value === false) return value;
  if (value === null || value === undefined || value === "") return null;
  const normalized = String(value).trim().toLowerCase();
  if (["true", "yes", "y", "1"].includes(normalized)) return true;
  if (["false", "no", "n", "0"].includes(normalized)) return false;
  return null;
}

function getValueByPath(obj, path) {
  return path.split(".").reduce((curr, key) => curr?.[key], obj);
}

// Recursively counts, for a section's saved data vs. its blank INITIAL_FORM
// default, how many individual leaf fields (scalars/booleans/flat arrays)
// actually hold RN-entered content vs. how many total leaf fields the
// section defines. This replaces the old "does ANYTHING differ from
// blank" check (which marked a 30-field section "Complete" because 1
// field changed) with a real documentation-completeness ratio, without
// hardcoding per-section field lists -- it walks whatever shape
// INITIAL_FORM[section] defines, so it stays correct as sections evolve.
//
// - Plain objects: recurse into each key and sum leaf counts.
// - Arrays of objects with a stable default length (e.g. the 16-item HOPE
//   education-topics scaffold, or per-item DME/equipment lists) are walked
//   element-by-element so real per-row documentation (a topic actually
//   marked taught/understood, an item's status actually set) counts,
//   instead of the array's mere existence counting as "populated."
// - Any other array is one leaf field, populated if it has any entries.
// - Scalars/booleans/strings are one leaf field each, populated if they
//   differ from the blank default (non-empty string, non-null, etc).
function countSectionCompletion(current, initial) {
  if (Array.isArray(initial)) {
    const allObjects = initial.length > 0 && initial.every((item) => item && typeof item === "object" && !Array.isArray(item));
    if (allObjects && Array.isArray(current) && current.length === initial.length) {
      return initial.reduce(
        (acc, initialItem, idx) => {
          const sub = countSectionCompletion(current[idx], initialItem);
          return { total: acc.total + sub.total, populated: acc.populated + sub.populated };
        },
        { total: 0, populated: 0 }
      );
    }
    const hasEntries = Array.isArray(current) && current.length > 0;
    return { total: 1, populated: hasEntries ? 1 : 0 };
  }
  if (initial && typeof initial === "object") {
    return Object.keys(initial).reduce(
      (acc, key) => {
        const sub = countSectionCompletion(current?.[key], initial[key]);
        return { total: acc.total + sub.total, populated: acc.populated + sub.populated };
      },
      { total: 0, populated: 0 }
    );
  }
  const isBlank = current === initial || current === "" || current === null || current === undefined;
  return { total: 1, populated: isBlank ? 0 : 1 };
}

// A section only earns the "Complete" badge once a meaningful share of its
// fields are actually documented -- not merely different from blank in one
// spot. 0.5 (half the section's fields) is the bar for "Complete"; any
// nonzero-but-below-threshold documentation is surfaced as "In Progress"
// instead of silently staying "Not started" or falsely reading "Complete".
const SECTION_COMPLETION_RATIO_THRESHOLD = 0.5;

function getSectionCompletionState(current, initial) {
  const { total, populated } = countSectionCompletion(current, initial);
  const ratio = total > 0 ? populated / total : 0;
  if (populated === 0) return { status: "not_started", ratio, populated, total };
  if (ratio >= SECTION_COMPLETION_RATIO_THRESHOLD) return { status: "complete", ratio, populated, total };
  return { status: "in_progress", ratio, populated, total };
}

function formatLcdRule(rule) {
  switch ((rule || "").toUpperCase()) {
    case "ALL_REQUIRED": return "ALL must be met";
    case "ANY_REQUIRED": return "ANY ONE may satisfy";
    case "ANY_3_REQUIRED": return "ANY 3 must be met";
    default: return rule || "Rule";
  }
}

function formatActualValue(value) {
  if (value === null || value === undefined || value === "") return "Unknown";
  if (value === true) return "Yes";
  if (value === false) return "No";
  return String(value);
}

function isCriteriaAnswerField(field) {
  return String(field || "").startsWith("criteria_answers.");
}

function buildClientLcdFacts(formData) {
  const weightLoss = parseWeightLoss(formData?.nutrition?.weightLossPastSixMonths);
  const adlValues = [
    formData?.musculoskeletal?.adl?.bathing,
    formData?.musculoskeletal?.adl?.dressing,
    formData?.musculoskeletal?.adl?.toileting,
    formData?.musculoskeletal?.adl?.transferring,
    formData?.musculoskeletal?.adl?.eating,
    formData?.musculoskeletal?.adl?.grooming,
  ]
    .map((value) => normalizeLcdNumber(value))
    .filter((value) => value !== null);
  const adlDependencyCount = adlValues.length
    ? adlValues.filter((value) => value >= 3).length
    : null;
  const swallowingIssues = formData?.nutrition?.swallowingIssues || [];
  const urinaryStatus = (formData?.genitourinary?.urinaryStatus || "").toLowerCase();
  // PRODUCT OWNER DIRECTIVE (2026-11-10) "CORRECT THE GI BOWEL DATA MODEL" --
  // reads the new `continence` field first, falls back to the legacy
  // `bowelStatus` enum for historical charts that never populated the new
  // field (see getEffectiveBowelContinence above). LCD scoring behavior is
  // unchanged for every existing chart; only the source field preference
  // changed.
  const bowelStatus = getEffectiveBowelContinence(formData?.gastrointestinal).toLowerCase();
  const pulse = normalizeLcdNumber(formData?.vitals?.pulse);
  const pps = normalizeLcdNumber(formData?.performanceStatus?.pps);
  const kps = normalizeLcdNumber(formData?.performanceStatus?.kps);
  const dressingScore = normalizeLcdNumber(formData?.musculoskeletal?.adl?.dressing);
  const bathingScore = normalizeLcdNumber(formData?.musculoskeletal?.adl?.bathing);
  // PRODUCT OWNER DIRECTIVE (2026-10-16) "Musculoskeletal Architecture
  // Review" -- `mobility.ambulatoryStatus` is retired from Musculoskeletal
  // ("should have been documented in Functional Status / ADLs from the
  // beginning"); the two LCD facts that read it are refactored to consume
  // the Functional Status / ADL source of truth instead of a derived
  // substitute: `ambulation_assistance_required` now reads the ADL
  // Transferring dependency score, same ADL-score-threshold pattern
  // already used two lines below for `dressing_assistance_required`/
  // `bathing_assistance_required`; `is_bedbound` now reads the Palliative
  // Performance Scale (PPS), whose standard descriptor defines 10%-20% as
  // "Totally Bed Bound" -- a true Functional Status-domain source, not a
  // Musculoskeletal concept.
  const transferScore = normalizeLcdNumber(formData?.musculoskeletal?.adl?.transferring);
  // OWNER DIRECTIVE (2026-10-29) "GI Rework" -- ostomy.present now stores
  // "Yes"/"No"/"" (segmentedTriState); normalizeTriState also accepts a
  // pre-existing legacy boolean `true`, so LCD scoring on historical
  // records is unaffected.
  // PRODUCT OWNER DIRECTIVE (2026-10-15) "GU Catheter Workflow
  // Finalization" -- "Retention"/"Painful urination"/"Nocturia" used to
  // be possible `urinaryStatus` values (so documenting a symptom alone,
  // with no continence state selected, already counted as "continence
  // evidence present" here). Now that those three symptoms live on the
  // separate `urinarySymptoms` field, that field must also be checked
  // so this LCD fact's presence/absence semantics are unchanged for
  // every existing and future chart -- a symptom-only chart still
  // counts as evidence present, exactly as it did before the split.
  const hasUrinarySymptomEvidence = (formData?.genitourinary?.urinarySymptoms || []).length > 0;
  const hasContinenceEvidence = Boolean(urinaryStatus || bowelStatus || formData?.genitourinary?.catheter?.present || hasUrinarySymptomEvidence) || normalizeTriState(formData?.gastrointestinal?.ostomy?.present) === "Yes";
  const hasWeightLossEvidence = weightLoss.lbs !== null || weightLoss.percent !== null;

  return {
    pps,
    kps,
    nyha_class: formData?.performanceStatus?.nyha || null,
    fast_stage: normalizeFastStage(formData?.performanceStatus?.fast),
    fast_stage_at_or_beyond_7a: fastStageAtOrBeyond7a(formData?.performanceStatus?.fast),
    weight_loss_lbs: weightLoss.lbs,
    weight_loss_percent_6_months: weightLoss.percent,
    continued_weight_loss: hasWeightLossEvidence ? (weightLoss.lbs ?? weightLoss.percent) > 0 : null,
    adl_dependency_count: adlDependencyCount,
    ambulation_assistance_required: transferScore !== null ? transferScore >= 3 : null,
    dressing_assistance_required: dressingScore !== null ? dressingScore >= 3 : null,
    bathing_assistance_required: bathingScore !== null ? bathingScore >= 3 : null,
    incontinence_or_catheter_ostomy_dependency: hasContinenceEvidence
      ? (
          ["stress incontinence", "urge incontinence", "functional incontinence", "total incontinence", "catheterized"].includes(urinaryStatus)
          || bowelStatus === "incontinent"
          || Boolean(formData?.genitourinary?.catheter?.present)
          || normalizeTriState(formData?.gastrointestinal?.ostomy?.present) === "Yes"
        )
      : null,
    is_bedbound: pps !== null ? pps <= 20 : null,
    dysphagia: swallowingIssues.includes("Dysphagia"),
    oral_intake_decline:
      ["poor", "anorexic"].includes((formData?.nutrition?.appetite || "").toLowerCase())
      || ["decreased", "minimal"].includes((formData?.nutrition?.fluidIntake || "").toLowerCase()),
    o2_sat_percent: normalizeLcdNumber(formData?.vitals?.oxygenSaturation) ?? normalizeLcdNumber(formData?.respiratory?.oxygenTherapy?.satOnO2),
    resting_tachycardia_gt_100: pulse !== null ? pulse > 100 : null,
    serum_albumin: normalizeLcdNumber(formData?.diagnoses?.ndsEligibility?.criteriaFacts?.[formData?.diagnoses?.ndsEligibility?.detectedDisease || ""]?.serum_albumin),
    serum_creatinine: normalizeLcdNumber(formData?.diagnoses?.ndsEligibility?.criteriaFacts?.[formData?.diagnoses?.ndsEligibility?.detectedDisease || ""]?.serum_creatinine),
    creatinine_clearance: normalizeLcdNumber(formData?.diagnoses?.ndsEligibility?.criteriaFacts?.[formData?.diagnoses?.ndsEligibility?.detectedDisease || ""]?.creatinine_clearance),
    gfr: normalizeLcdNumber(formData?.diagnoses?.ndsEligibility?.criteriaFacts?.[formData?.diagnoses?.ndsEligibility?.detectedDisease || ""]?.gfr),
    po2: normalizeLcdNumber(formData?.diagnoses?.ndsEligibility?.criteriaFacts?.[formData?.diagnoses?.ndsEligibility?.detectedDisease || ""]?.po2),
    pco2: normalizeLcdNumber(formData?.diagnoses?.ndsEligibility?.criteriaFacts?.[formData?.diagnoses?.ndsEligibility?.detectedDisease || ""]?.pco2),
    ejection_fraction: normalizeLcdNumber(formData?.diagnoses?.ndsEligibility?.criteriaFacts?.[formData?.diagnoses?.ndsEligibility?.detectedDisease || ""]?.ejection_fraction),
    cd4_count: normalizeLcdNumber(formData?.diagnoses?.ndsEligibility?.criteriaFacts?.[formData?.diagnoses?.ndsEligibility?.detectedDisease || ""]?.cd4_count),
    viral_load: normalizeLcdNumber(formData?.diagnoses?.ndsEligibility?.criteriaFacts?.[formData?.diagnoses?.ndsEligibility?.detectedDisease || ""]?.viral_load),
  };
}

function buildLcdEvaluationPayload(formData, disease) {
  const criteriaAnswers = formData?.diagnoses?.ndsEligibility?.criteriaAnswers?.[disease] || {};
  const criteriaFacts = formData?.diagnoses?.ndsEligibility?.criteriaFacts?.[disease] || {};
  const facts = {
    ...buildClientLcdFacts(formData),
    ...criteriaFacts,
    criteria_answers: disease ? { [disease]: criteriaAnswers } : {},
  };

  return {
    patient: {
      ...formData,
      assessment: formData,
      disease,
      primary_diagnosis_description: formData?.diagnoses?.primaryDiagnosis?.description || "",
      primary_diagnosis_code: formData?.diagnoses?.primaryDiagnosis?.icd10 || "",
    },
    facts,
  };
}

function LcdTernaryButtons({ value, onChange, COLORS }) {
  const options = [
    { key: true, label: "Yes" },
    { key: false, label: "No" },
    { key: null, label: "Unknown" },
  ];
  return (
    <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
      {options.map((option) => {
        const active = value === option.key;
        return (
          <button
            key={String(option.key)}
            type="button"
            onClick={() => onChange(option.key)}
            style={{
              padding: "4px 10px",
              borderRadius: 999,
              border: `1px solid ${active ? COLORS.teal : COLORS.border}`,
              background: active ? COLORS.tealBg : COLORS.white,
              color: COLORS.dark,
              fontSize: 12,
              fontWeight: 700,
              cursor: "pointer",
            }}
          >
            {option.label}
          </button>
        );
      })}
    </div>
  );
}

function LcdEligibilityCard({ diagnosesData, fullFormData, updateField, styles, COLORS, workspacePilot = false }) {
  const diagnosisText = `${diagnosesData?.primaryDiagnosis?.icd10 || ""} ${diagnosesData?.primaryDiagnosis?.description || ""}`.trim();
  const detectedDisease = diagnosesData?.ndsEligibility?.detectedDisease || "";
  const criteriaAnswers = diagnosesData?.ndsEligibility?.criteriaAnswers?.[detectedDisease] || {};
  const criteriaFacts = diagnosesData?.ndsEligibility?.criteriaFacts?.[detectedDisease] || {};
  const [config, setConfig] = useState(null);
  const [configLoading, setConfigLoading] = useState(false);
  const [configError, setConfigError] = useState("");
  const [evaluation, setEvaluation] = useState(null);
  const [evaluationLoading, setEvaluationLoading] = useState(false);
  const [evaluationError, setEvaluationError] = useState("");

  const updateDiagnoses = useCallback((path, value) => {
    updateField(path, value);
  }, [updateField]);

  useEffect(() => {
    if (!diagnosisText) {
      if (detectedDisease) updateDiagnoses("ndsEligibility.detectedDisease", "");
      setConfig(null);
      setEvaluation(null);
      setConfigError("");
      return;
    }

    const handle = window.setTimeout(async () => {
      try {
        const detected = await detectLCD(diagnosisText);
        if (detected?.disease && detected.disease !== detectedDisease) {
          updateDiagnoses("ndsEligibility.detectedDisease", detected.disease);
        }
      } catch (error) {
        console.error("LCD disease detection failed:", error);
        setConfigError(error instanceof Error ? error.message : "Unable to detect LCD disease.");
      }
    }, 250);

    return () => window.clearTimeout(handle);
  }, [diagnosisText, detectedDisease, updateDiagnoses]);

  useEffect(() => {
    if (!detectedDisease) {
      setConfig(null);
      return;
    }

    let active = true;
    setConfigLoading(true);
    setConfigError("");
    getLCDConfig(detectedDisease)
      .then((data) => {
        if (active) setConfig(data);
      })
      .catch((error) => {
        if (!active) return;
        console.error("LCD config load failed:", error);
        setConfig(null);
        setConfigError(error instanceof Error ? error.message : "Unable to load LCD config.");
      })
      .finally(() => {
        if (active) setConfigLoading(false);
      });

    return () => {
      active = false;
    };
  }, [detectedDisease]);

  const evaluationPayload = useMemo(
    () => (detectedDisease ? buildLcdEvaluationPayload(fullFormData, detectedDisease) : null),
    [fullFormData, detectedDisease],
  );

  useEffect(() => {
    if (!detectedDisease || !config || !evaluationPayload) {
      setEvaluation(null);
      return;
    }

    let active = true;
    const handle = window.setTimeout(async () => {
      setEvaluationLoading(true);
      setEvaluationError("");
      try {
        const result = await evaluateLCD(
          evaluationPayload.patient,
          evaluationPayload.facts,
        );
        if (active) setEvaluation(result);
      } catch (error) {
        if (!active) return;
        console.error("LCD evaluation failed:", error);
        setEvaluation(null);
        setEvaluationError(error instanceof Error ? error.message : "Unable to evaluate LCD eligibility.");
      } finally {
        if (active) setEvaluationLoading(false);
      }
    }, 250);

    return () => {
      active = false;
      window.clearTimeout(handle);
    };
  }, [detectedDisease, config, evaluationPayload]);

  const setCriteriaAnswer = useCallback((criterionId, value) => {
    updateDiagnoses(`ndsEligibility.criteriaAnswers.${detectedDisease}.${criterionId}`, value);
  }, [detectedDisease, updateDiagnoses]);

  const setCriteriaFact = useCallback((field, value) => {
    updateDiagnoses(`ndsEligibility.criteriaFacts.${detectedDisease}.${field}`, value);
  }, [detectedDisease, updateDiagnoses]);

  const groupResults = evaluation?.criteria_summary?.group_results || [];
  const criterionDetails = useMemo(() => {
    const map = new Map();
    groupResults.forEach((group) => {
      (group.criteria || []).forEach((criterion) => {
        map.set(`${group.group_id}:${criterion.criterion_id}`, criterion);
      });
    });
    return map;
  }, [groupResults]);

  const groupSummaries = useMemo(() => {
    return (config?.criteria_groups || []).map((group) => {
      let met = 0;
      let unmet = 0;
      let unknown = 0;
      (group.criteria || []).forEach((criterion) => {
        const detail = criterionDetails.get(`${group.group_id}:${criterion.criterion_id}`);
        if (!detail || detail.actual === null || detail.actual === undefined || detail.actual === "") {
          unknown += 1;
        } else if (detail.matched) {
          met += 1;
        } else {
          unmet += 1;
        }
      });
      return { group, met, unmet, unknown };
    });
  }, [config, criterionDetails]);
  const criterionSummary = useMemo(
    () => groupSummaries.reduce(
      (summary, group) => ({
        met: summary.met + group.met,
        unmet: summary.unmet + group.unmet,
        unknown: summary.unknown + group.unknown,
      }),
      { met: 0, unmet: 0, unknown: 0 },
    ),
    [groupSummaries],
  );
  const orderedGroupSummaries = useMemo(
    () => workspacePilot
      ? [...groupSummaries].sort((a, b) => {
          const aNeedsReview = a.unmet + a.unknown > 0 ? 0 : 1;
          const bNeedsReview = b.unmet + b.unknown > 0 ? 0 : 1;
          return aNeedsReview - bNeedsReview;
        })
      : groupSummaries,
    [groupSummaries, workspacePilot],
  );
  const [expandedGroups, setExpandedGroups] = useState(() => new Set());
  const [collapsedGroups, setCollapsedGroups] = useState(() => new Set());
  useEffect(() => {
    setExpandedGroups(new Set());
    setCollapsedGroups(new Set());
  }, [detectedDisease]);
  const toggleGroup = (groupId, isOpen) => {
    if (isOpen) {
      setExpandedGroups((current) => {
        const next = new Set(current);
        next.delete(groupId);
        return next;
      });
      setCollapsedGroups((current) => new Set(current).add(groupId));
      return;
    }
    setCollapsedGroups((current) => {
      const next = new Set(current);
      next.delete(groupId);
      return next;
    });
    setExpandedGroups((current) => new Set(current).add(groupId));
  };

  const supplementalValueFor = (field) => criteriaFacts?.[field] ?? "";
  const currentFacts = evaluationPayload?.facts || {};

  const renderCriterionInput = (criterion) => {
    if (isCriteriaAnswerField(criterion.field)) {
      return (
        <LcdTernaryButtons
          value={normalizeYesNoUnknown(criteriaAnswers?.[criterion.criterion_id])}
          onChange={(value) => setCriteriaAnswer(criterion.criterion_id, value)}
          COLORS={COLORS}
        />
      );
    }

    if (LCD_AUTO_FACT_FIELDS.has(criterion.field)) {
      const detail = criterionDetails.get(`${criterion.group_id}:${criterion.criterion_id}`);
      return (
        <div style={{ fontSize: 12, color: COLORS.gray, lineHeight: 1.45 }}>
          <div><strong style={{ color: COLORS.dark }}>{detail?.matched ? "✓ Met" : "✗ Not met"}</strong> — current value: {formatActualValue(detail?.actual ?? currentFacts?.[criterion.field])}</div>
          <div>Auto-filled from other RNICA sections.</div>
        </div>
      );
    }

    if (typeof criterion.expected === "number" && ["LT", "LTE", "GT", "GTE"].includes(String(criterion.operator || "").toUpperCase())) {
      return (
        <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
          <input
            type="number"
            value={supplementalValueFor(criterion.field)}
            onChange={(event) => setCriteriaFact(criterion.field, event.target.value === "" ? "" : Number(event.target.value))}
            style={{ ...styles.input, width: 120, padding: "5px 8px" }}
          />
          <button
            type="button"
            onClick={() => setCriteriaFact(criterion.field, "")}
            style={{ ...styles.btnSecondary, padding: "5px 10px", fontSize: 12 }}
          >
            Unknown
          </button>
        </div>
      );
    }

    return (
      <LcdTernaryButtons
        value={normalizeYesNoUnknown(criteriaFacts?.[criterion.field])}
        onChange={(value) => setCriteriaFact(criterion.field, value)}
        COLORS={COLORS}
      />
    );
  };

  return (
    <div>
      {!diagnosisText && (
        <div style={{ ...styles.infoBox, marginBottom: 10 }}>
          Enter the primary diagnosis ICD-10 and/or description above to load the matching LCD disease-specific criteria.
        </div>
      )}

      {diagnosisText && (
        <div className={workspacePilot ? "rnica-lcd-summary" : undefined} style={{ ...styles.infoBox, marginBottom: 10, padding: 12 }}>
          <div style={{ display: "flex", justifyContent: "space-between", gap: 12, flexWrap: "wrap" }}>
            <div>
              <div style={{ fontWeight: 800, marginBottom: 2 }}>
                {detectedDisease ? detectedDisease.replaceAll("_", " ") : "Detecting LCD disease..."}
              </div>
              {config?.lcd_reference && <div style={{ fontSize: 12, color: COLORS.gray }}>{config.lcd_reference}</div>}
            </div>
            <div style={{
              ...styles.statusBadge,
              background: evaluation?.eligible ? COLORS.successBoxBg : COLORS.warningBoxBg,
              color: COLORS.dark,
              border: `1px solid ${evaluation?.eligible ? "rgba(16,185,129,0.26)" : "rgba(245,158,11,0.3)"}`,
            }}>
              {evaluationLoading ? "Evaluating..." : evaluation?.eligible ? "Eligible" : "Not eligible"}
            </div>
          </div>
          {workspacePilot && (
            <div className="rnica-lcd-summary__counts" aria-label="LCD criterion summary">
              <span><strong>{criterionSummary.met}</strong> met</span>
              <span><strong>{criterionSummary.unmet}</strong> unmet</span>
              <span><strong>{criterionSummary.unknown}</strong> unknown</span>
            </div>
          )}
          {config?.source_document && <div style={{ fontSize: 11, color: COLORS.gray, marginTop: 6 }}>Source: {config.source_document}</div>}
        </div>
      )}

      {(configError || evaluationError) && (
        <div style={{ ...styles.warningBox, marginBottom: 10, padding: 12 }}>
          {configError || evaluationError}
        </div>
      )}

      {configLoading && <div style={{ fontSize: 12, color: COLORS.gray, marginBottom: 8 }}>Loading LCD criteria…</div>}

      {orderedGroupSummaries.map(({ group, met, unmet, unknown }) => {
        const groupResult = groupResults.find((item) => item.group_id === group.group_id);
        const needsReview = unmet + unknown > 0;
        // FR-007: LCD groups are collapsed by default in the pilot
        // workspace -- expand only on explicit RN toggle. (Previously a
        // group needing review auto-expanded; the owner directive is
        // explicit that collapsed-by-default applies unconditionally, so
        // the RN reviews the met/unmet/unknown counts first and opens a
        // group deliberately.)
        const groupOpen = !workspacePilot || expandedGroups.has(group.group_id);
        const groupBadges = (
          <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
            {workspacePilot && <span className="rnica-lcd-group__count">{met} met · {unmet} unmet · {unknown} unknown</span>}
            <span style={styles.cmsTag}>{formatLcdRule(group.rule)}</span>
            {groupResult && (
              <span style={{
                ...styles.statusBadge,
                padding: "3px 8px",
                background: groupResult.passed ? COLORS.successBoxBg : COLORS.warningBoxBg,
                color: COLORS.dark,
                border: `1px solid ${groupResult.passed ? "rgba(16,185,129,0.26)" : "rgba(245,158,11,0.3)"}`,
              }}>
                {groupResult.passed ? "Pass" : "Fail"}
              </span>
            )}
          </div>
        );
        return (
          <div
            key={group.group_id}
            className={workspacePilot ? `rnica-lcd-group ${needsReview ? "needs-review" : "is-satisfied"}` : undefined}
            style={{
              border: `1px solid ${COLORS.border}`,
              borderRadius: 10,
              padding: 10,
              marginBottom: 10,
              background: COLORS.bg,
            }}
          >
            {workspacePilot ? (
              <button type="button" className="rnica-lcd-group__toggle" aria-expanded={groupOpen} onClick={() => toggleGroup(group.group_id, groupOpen)}>
                <span>{groupOpen ? "▾" : "▸"} {group.group_name}</span>
                {groupBadges}
              </button>
            ) : (
              <div style={{ display: "flex", justifyContent: "space-between", gap: 8, alignItems: "center", marginBottom: 8, flexWrap: "wrap" }}>
                <div style={{ fontSize: 13, fontWeight: 800, color: COLORS.dark }}>{group.group_name}</div>
                {groupBadges}
              </div>
            )}
            {groupOpen && <div className={workspacePilot ? "rnica-lcd-criteria" : undefined} style={{ display: "flex", flexDirection: "column", gap: 8 }}>
              {(group.criteria || []).map((criterion) => {
                const detail = criterionDetails.get(`${group.group_id}:${criterion.criterion_id}`);
                const criterionWithGroup = { ...criterion, group_id: group.group_id };
                return (
                  <div
                    key={criterion.criterion_id}
                    className={workspacePilot ? "rnica-lcd-criterion" : undefined}
                    style={{
                      display: "grid",
                      gridTemplateColumns: "minmax(0, 1fr) auto",
                      gap: 10,
                      alignItems: "center",
                      padding: "8px 10px",
                      borderRadius: 8,
                      border: `1px solid ${COLORS.border}`,
                      background: COLORS.white,
                    }}
                  >
                    <div>
                      <div style={{ fontSize: 12.5, fontWeight: 700, color: COLORS.dark }}>{criterion.criterion_id}. {criterion.description}</div>
                      {detail && (
                        <div style={{ fontSize: 11, color: COLORS.gray, marginTop: 3 }}>
                          Current: {formatActualValue(detail.actual)} • Expected: {formatActualValue(detail.expected)}
                        </div>
                      )}
                    </div>
                    <div style={{ minWidth: 180 }}>
                      {renderCriterionInput(criterionWithGroup)}
                    </div>
                  </div>
                );
              })}
            </div>}
          </div>
        );
      })}
      {!workspacePilot && (
        <div>
          <FormTextarea
            label="LCD supporting evidence"
            value={diagnosesData?.lcdEligibilityNarrative || ""}
            onChange={(value) => updateDiagnoses("lcdEligibilityNarrative", value)}
            placeholder="Document evidence specific to the selected LCD guideline. This is not the whole-patient clinical narrative."
            rows={4}
          />
        </div>
      )}
    </div>
  );
}

// In the pilot workflow, structured checklists (LCD criteria, secondary
// diagnoses, comorbidities) render first; this free-text LCD evidence card
// renders last on the Diagnoses page so no narrative sits mid-page.
function LcdSupportingEvidenceCard({ diagnosesData, updateField }) {
  return (
    <div className="rnica-lcd-evidence">
      <FormTextarea
        label="LCD supporting evidence"
        value={diagnosesData?.lcdEligibilityNarrative || ""}
        onChange={(value) => updateField("lcdEligibilityNarrative", value)}
        placeholder="Document evidence specific to the selected LCD guideline. This is not the whole-patient clinical narrative."
        rows={4}
      />
    </div>
  );
}

// ════════════════════════════════════════════════════════════════
// SECTION 10 — Clinical Narrative & Disease Trajectory.
//
// This card is deliberately separate from LcdEligibilityCard /
// lcdEligibilityNarrative (distinct field, distinct purpose — the RN's
// documented clinical findings narrative vs. the physician's LCD
// eligibility-support narrative). The deterministic
// buildClinicalNarrative() template renderer runs ONLY on an explicit
// "Build Draft from Documented Findings" click — never on mount, never
// on formData changes, never during save/validation/navigation. No AI
// service, AI flag, or AI control exists anywhere in this card.
// ════════════════════════════════════════════════════════════════
function ClinicalNarrativeCard({ diagnosesData, fullFormData, updateField, styles, COLORS, locked }) {
  const [pendingReplace, setPendingReplace] = useState(false);
  const narrative = diagnosesData?.clinicalNarrative || "";
  const trajectory = diagnosesData?.diseaseTrajectory || "";
  const isLegacyTrajectory = isLegacyDiseaseTrajectoryValue(trajectory);

  const handleBuildDraft = () => {
    if (narrative.trim()) {
      setPendingReplace(true);
      return;
    }
    applyDraft();
  };

  const applyDraft = () => {
    const draft = buildClinicalNarrative(fullFormData, {});
    updateField("clinicalNarrative", draft.text);
    // Replacing the narrative content always resets review — a
    // previously reviewed narrative cannot remain "reviewed" once its
    // text has changed.
    updateField("clinicalNarrativeReviewed", false);
    setPendingReplace(false);
  };

  const handleNarrativeChange = (value) => {
    updateField("clinicalNarrative", value);
    updateField("clinicalNarrativeReviewed", false);
  };

  return (
    <div>
      <div style={styles.formGroup}>
        <label style={styles.label}>Disease Trajectory</label>
        <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
          {DISEASE_TRAJECTORY_OPTIONS.map((opt) => (
            <label key={opt.value} style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13, color: COLORS.dark }}>
              <input
                type="radio"
                name="diseaseTrajectory"
                value={opt.value}
                checked={trajectory === opt.value}
                disabled={locked}
                onChange={() => updateField("diseaseTrajectory", opt.value)}
              />
              {opt.label}
            </label>
          ))}
        </div>
        {isLegacyTrajectory && (
          <div style={{ marginTop: 6, fontSize: 12, color: COLORS.warning }}>
            Legacy value on file: "{trajectory}". This was recorded before the current trajectory options existed and is not
            automatically converted — please review and select one of the options above.
          </div>
        )}
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))", gap: 16 }}>
        <FormInput
          label="Recent Hospitalizations (count)"
          type="number"
          value={diagnosesData?.recentHospitalizations ?? ""}
          onChange={(v) => updateField("recentHospitalizations", v)}
          disabled={locked}
          min={0}
          step={1}
          placeholder="Leave blank if not documented"
        />
        <FormInput
          label="Recent Emergency Department Visits (count)"
          type="number"
          value={diagnosesData?.recentErVisits ?? ""}
          onChange={(v) => updateField("recentErVisits", v)}
          disabled={locked}
          min={0}
          step={1}
          placeholder="Leave blank if not documented"
        />
      </div>
      <FormTextarea
        label="Utilization Notes"
        value={diagnosesData?.utilizationNotes}
        onChange={(v) => updateField("utilizationNotes", v)}
        rows={2}
        disabled={locked}
      />

      <div style={{ marginTop: 12, marginBottom: 8 }}>
        <button
          type="button"
          style={{ ...styles.btnSecondary, opacity: locked ? 0.5 : 1 }}
          onClick={handleBuildDraft}
          disabled={locked}
        >
          Build Draft from Documented Findings
        </button>
        <span style={{ marginLeft: 10, fontSize: 11.5, color: COLORS.gray }}>
          Assembles a draft strictly from already-documented fields on this assessment. It never runs automatically and never
          determines eligibility, prognosis, or disease trajectory.
        </span>
      </div>

      {pendingReplace && (
        <div style={{
          padding: 10, borderRadius: 8, border: `1px solid ${COLORS.warning}`,
          background: COLORS.warningBoxBg, marginBottom: 10, fontSize: 12.5, color: COLORS.dark,
        }}>
          <div style={{ marginBottom: 8 }}>A clinical narrative already exists. Building a new draft will replace the current text.</div>
          <button type="button" style={styles.btnSecondary} onClick={() => setPendingReplace(false)}>Keep Existing Narrative</button>
          <button type="button" style={{ ...styles.btnPrimary, marginLeft: 8 }} onClick={applyDraft}>Replace with New Draft</button>
        </div>
      )}

      <FormTextarea
        label="Diagnoses Narrative"
        value={narrative}
        onChange={handleNarrativeChange}
        rows={10}
        disabled={locked}
        placeholder="Document the patient's clinical presentation and supporting findings in your own words, or click Build Draft from Documented Findings above."
      />

      <div style={{ display: "flex", alignItems: "center", gap: 8, margin: "8px 0 16px" }}>
        <input
          type="checkbox"
          id="clinicalNarrativeReviewed"
          checked={!!diagnosesData?.clinicalNarrativeReviewed}
          disabled={locked}
          onChange={(e) => updateField("clinicalNarrativeReviewed", e.target.checked)}
        />
        <label htmlFor="clinicalNarrativeReviewed" style={{ fontSize: 13, color: COLORS.dark }}>
          I reviewed this narrative and verified that it matches the documented assessment findings.
        </label>
      </div>

      <FormTextarea
        label="RN Addendum"
        value={diagnosesData?.rnAddendum}
        onChange={(v) => updateField("rnAddendum", v)}
        rows={3}
        disabled={locked}
      />
      <FormTextarea
        label="Clinician Clarification"
        value={diagnosesData?.clinicianClarification}
        onChange={(v) => updateField("clinicianClarification", v)}
        rows={3}
        disabled={locked}
      />
      {locked && (
        <div style={{ fontSize: 11.5, color: COLORS.gray }}>
          This assessment is locked/authenticated. Section 10 fields are read-only. Additional post-authentication information
          must be captured as a distinct, traceable, authenticated addendum record — a documented gap in current SNS EMR
          infrastructure, not implemented as an editable field on this locked assessment.
        </div>
      )}
    </div>
  );
}

// Shared chip visual language (Pain Character / Neuropathic
// Characteristics / Aggravating / Relieving Factors use the exact same
// recipe via ui/toggle-group.tsx's ToggleGroupItem). Reused directly as a
// plain-button className here (rather than ToggleGroupItem) wherever a
// chip needs per-item disabled/detected decoration that Radix's grouped
// value-diffing doesn't support cleanly -- same classes, same
// data-state="on"/"off" selected styling, so it is visually identical.
const RNICA_CHIP_CLASS =
  "inline-flex items-center gap-1 whitespace-nowrap rounded-full border px-[9px] py-[2px] text-[11px] leading-[1.6] " +
  "bg-transparent border-rnica-border text-rnica-text font-medium transition-colors hover:border-rnica-teal " +
  "focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-rnica-focusRing " +
  "disabled:cursor-not-allowed disabled:opacity-40 " +
  "data-[state=on]:border-rnica-teal data-[state=on]:bg-rnica-teal data-[state=on]:text-rnica-textInverse data-[state=on]:font-bold";

// Small reusable "info" affordance -- converts an explanatory paragraph
// into a hover/focus tooltip instead of permanent on-screen text, per the
// "convert explanations to info tooltips" directive already applied to
// Comorbidities/Pain/Neuro. Wraps its own TooltipProvider so it can be
// dropped in anywhere without depending on a root-level provider.
function InfoTooltip({ text }) {
  return (
    <TooltipProvider delayDuration={200}>
      <Tooltip>
        <TooltipTrigger asChild>
          <button
            type="button"
            aria-label="More information"
            className="inline-flex h-4 w-4 shrink-0 items-center justify-center rounded-full border border-rnica-border text-[10px] font-semibold leading-none text-rnica-muted hover:border-rnica-teal hover:text-rnica-teal"
          >
            i
          </button>
        </TooltipTrigger>
        <TooltipContent className="max-w-[260px] text-left normal-case">{text}</TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
}

// Determines what removing a secondary-diagnosis row would change
// downstream (HopeComorbiditiesCard's ICD-10 category auto-detect dots,
// which can feed the LCD Evidence Summary + "Comorbidities reviewed"
// verification item) so the remove action can ask for confirmation only
// when removal is not a no-op. Mirrors HopeComorbiditiesCard's own
// `autoDetected` derivation exactly (categorizeIcd10 over every OTHER
// row's icd10) -- keep the two in sync if that logic ever changes.
function describeSecondaryDiagnosisRemovalImpact(rows, idx, hope) {
  const target = rows[idx];
  if (!target) return null;
  const remaining = rows.filter((_, i) => i !== idx);
  const detectedBefore = new Set();
  rows.forEach((dx) => {
    const cat = categorizeIcd10(dx?.icd10);
    if (cat) detectedBefore.add(cat.key);
  });
  const detectedAfter = new Set();
  remaining.forEach((dx) => {
    const cat = categorizeIcd10(dx?.icd10);
    if (cat) detectedAfter.add(cat.key);
  });
  const lostCategories = [...detectedBefore].filter((key) => !detectedAfter.has(key) && hope?.[key]);
  const wasOnlyDiagnosis = rows.filter((dx) => dx?.icd10 || dx?.description).length === 1 && (target.icd10 || target.description);
  if (lostCategories.length === 0 && !wasOnlyDiagnosis) return null;
  const categoryLabels = lostCategories
    .map((key) => HOPE_COMORBIDITY_CATEGORIES.find((c) => c.key === key)?.shortLabel || HOPE_COMORBIDITY_CATEGORIES.find((c) => c.key === key)?.label)
    .filter(Boolean);
  return { categoryLabels, wasOnlyDiagnosis };
}

// A single secondary-diagnosis row's search box, mirroring
// PrimaryTerminalDiagnosisCard's merged "Search Diagnosis or ICD-10"
// control -- one Icd10DiagnosisInput fills both icd10 + description in
// one action instead of two separate manually-typed fields. Extracted to
// its own component (rather than inline in the rows.map below) so each
// row can hold its own local "what the RN is currently typing" state
// without violating the rules of hooks across a dynamic-length list.
function SecondaryDiagnosisSearchRow({ row, idx, updateRow, onRequestRemove, styles, COLORS }) {
  const [searchText, setSearchText] = useState(() => (
    row.description ? `${row.description}${row.icd10 ? ` (${formatIcd10Code(row.icd10)})` : ""}` : formatIcd10Code(row.icd10 || "")
  ));

  const handleSelectSuggestion = (suggestion) => {
    // Combine both field updates into one updateRow call -- two sequential
    // single-field calls would each compute their new array from the same
    // stale closure-captured `rows`, so the second call's result silently
    // overwrites the first (see the identical fix in
    // ContributingConditionRow.handleSelectSuggestion).
    updateRow(idx, { icd10: suggestion.icd10_code, description: suggestion.diagnosis_description });
  };

  // Flex "card" (not a fixed-width grid column) so the row wraps its own
  // content on narrow sheets instead of overflowing the editor's column
  // boundary -- the search input shrinks/grows while the toggle + remove
  // affordance stay a fixed size and drop to their own line if needed.
  return (
    <div className="rnica-diagnosis-card" role="row">
      <div className="rnica-diagnosis-card__search" role="cell">
        <Icd10DiagnosisInput
          value={searchText}
          onChange={setSearchText}
          onSelectSuggestion={handleSelectSuggestion}
          colors={{ cardBg: COLORS.white, border: COLORS.border, label: COLORS.gray, white: COLORS.dark }}
          inputStyle={styles.input}
          placeholder="Search diagnosis or ICD-10…"
        />
      </div>
      <div className="rnica-diagnosis-card__related" role="cell">
        <button
          type="button"
          className={RNICA_CHIP_CLASS}
          data-state={row.relatedToTerminal !== false ? "on" : "off"}
          onClick={() => updateRow(idx, "relatedToTerminal", true)}
        >
          Related
        </button>
        <button
          type="button"
          className={RNICA_CHIP_CLASS}
          data-state={row.relatedToTerminal === false ? "on" : "off"}
          onClick={() => updateRow(idx, "relatedToTerminal", false)}
        >
          Unrelated
        </button>
      </div>
      <button
        type="button"
        className="rnica-diagnosis-card__remove"
        title="Remove this secondary diagnosis"
        aria-label="Remove this secondary diagnosis"
        onClick={() => onRequestRemove(idx)}
      >
        <span aria-hidden="true">×</span>
      </button>
    </div>
  );
}

// ════════════════════════════════════════════════════════════════
// SECONDARY DIAGNOSES — add/edit/remove list (feeds HOPE comorbidity
// auto-detection below and hopeReportMapper.js diagnosisEntries()).
// ════════════════════════════════════════════════════════════════
function SecondaryDiagnosesCard({ diagnosesData, updateField, styles, COLORS, workspacePilot = false }) {
  const rows = diagnosesData?.secondaryDiagnoses || [];
  const [showAll, setShowAll] = useState(false);
  const [pendingRemoveIdx, setPendingRemoveIdx] = useState(null);
  const visibleRows = workspacePilot && !showAll ? rows.slice(0, 7) : rows;
  const hope = diagnosesData?.hopeComorbidities || {};

  const setRows = (next) => updateField("secondaryDiagnoses", next);

  const addRow = () => {
    setRows([...rows, { icd10: "", description: "", relatedToTerminal: true }]);
    if (workspacePilot) setShowAll(true);
  };

  const updateRow = (idx, field, value) => {
    const patch = typeof field === "object" && field !== null ? field : { [field]: value };
    setRows(rows.map((row, i) => (i === idx ? { ...row, ...patch } : row)));
  };

  const removeRow = (idx) => setRows(rows.filter((_, i) => i !== idx));

  // Empty/never-touched rows (just added, nothing searched yet) have no
  // downstream impact -- remove them immediately instead of interrupting
  // with a confirmation for a diagnosis that was never really "added".
  const requestRemove = (idx) => {
    const row = rows[idx];
    const impact = row?.icd10 || row?.description ? describeSecondaryDiagnosisRemovalImpact(rows, idx, hope) : null;
    if (impact) {
      setPendingRemoveIdx(idx);
    } else {
      removeRow(idx);
    }
  };

  const pendingImpact = pendingRemoveIdx !== null ? describeSecondaryDiagnosisRemovalImpact(rows, pendingRemoveIdx, hope) : null;

  if (workspacePilot) {
    return (
      <div className="rnica-diagnosis-ledger">
        <div className="rnica-diagnosis-ledger__summary">
          <span className="rnica-diagnosis-ledger__heading">
            Secondary Diagnoses
            <InfoTooltip text="Active diagnoses contributing to the plan of care. Related status does not add a diagnosis to the HOPE comorbidity checklist." />
          </span>
          <strong>{rows.length} {rows.length === 1 ? "diagnosis" : "diagnoses"}</strong>
        </div>
        {rows.length === 0 ? (
          <div className="rnica-diagnosis-ledger__empty">No secondary diagnoses added yet.</div>
        ) : (
          <div className="rnica-diagnosis-cards" aria-label="Secondary diagnoses">
            {visibleRows.map((row, idx) => (
              <SecondaryDiagnosisSearchRow
                key={idx}
                row={row}
                idx={idx}
                updateRow={updateRow}
                onRequestRemove={requestRemove}
                styles={styles}
                COLORS={COLORS}
              />
            ))}
          </div>
        )}
        <div className="rnica-diagnosis-ledger__actions">
          <button type="button" onClick={addRow}>+ Add secondary diagnosis</button>
          {rows.length > 7 && (
            <button type="button" onClick={() => setShowAll((current) => !current)} aria-expanded={showAll}>
              {showAll ? "Show fewer" : `Show all ${rows.length} diagnoses`}
            </button>
          )}
        </div>

        <AlertDialog open={pendingRemoveIdx !== null} onOpenChange={(next) => { if (!next) setPendingRemoveIdx(null); }}>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>Remove this secondary diagnosis?</AlertDialogTitle>
              <AlertDialogDescription>
                {pendingImpact?.categoryLabels?.length > 0 && (
                  <>
                    This diagnosis is the only one currently detecting the{" "}
                    <strong>{pendingImpact.categoryLabels.join(", ")}</strong> comorbidit{pendingImpact.categoryLabels.length === 1 ? "y" : "ies"}{" "}
                    checked below. The checked box will remain, but its auto-detected support will be removed.
                  </>
                )}
                {pendingImpact?.wasOnlyDiagnosis && (
                  <>
                    {pendingImpact?.categoryLabels?.length > 0 ? " Also, this" : "This"} is the only secondary diagnosis documented, so
                    removing it will clear the "Secondary diagnoses reviewed" verification item and the LCD Evidence Summary.
                  </>
                )}
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel onClick={() => setPendingRemoveIdx(null)}>Cancel</AlertDialogCancel>
              <AlertDialogAction
                onClick={() => {
                  removeRow(pendingRemoveIdx);
                  setPendingRemoveIdx(null);
                }}
              >
                Remove
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      </div>
    );
  }

  return (
    <div>
      <p style={{ fontSize: 12, color: COLORS.gray, marginTop: -4, marginBottom: 10 }}>
        All other active diagnoses contributing to the plan of care. Marking a diagnosis as
        "related to terminal illness" is used for hospice benefit-period documentation and does
        not by itself add it to the HOPE comorbidity checklist below.
      </p>
      {rows.length === 0 && (
        <div style={{ fontSize: 12.5, color: COLORS.gray, fontStyle: "italic", marginBottom: 10 }}>
          No secondary diagnoses added yet.
        </div>
      )}
      <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
        {rows.map((row, idx) => (
          <div
            key={idx}
            style={{
              display: "grid",
              gridTemplateColumns: "140px minmax(0, 1fr) auto auto",
              gap: 10,
              alignItems: "center",
              padding: "8px 10px",
              borderRadius: 8,
              border: `1px solid ${COLORS.border}`,
              background: COLORS.bg,
            }}
          >
            <input
              style={styles.input}
              placeholder="ICD-10"
              value={row.icd10 || ""}
              onChange={(e) => updateRow(idx, "icd10", e.target.value)}
            />
            <input
              style={styles.input}
              placeholder="Description"
              value={row.description || ""}
              onChange={(e) => updateRow(idx, "description", e.target.value)}
            />
            <label style={{ ...styles.checkboxLabel, whiteSpace: "nowrap" }}>
              <input
                type="checkbox"
                checked={row.relatedToTerminal !== false}
                onChange={(e) => updateRow(idx, "relatedToTerminal", e.target.checked)}
              />
              Related
            </label>
            <button type="button" style={{ ...styles.btnDanger, padding: "6px 10px" }} onClick={() => removeRow(idx)}>
              Remove
            </button>
          </div>
        ))}
      </div>
      <button type="button" style={{ ...styles.btnSecondary, marginTop: 10 }} onClick={addRow}>
        + Add Secondary Diagnosis
      </button>
    </div>
  );
}

// ════════════════════════════════════════════════════════════════
// CONTRIBUTING CONDITIONS — Disease & LCD Workflow Specification, Phase 1
// / Option A (owner directive). Manually-documented conditions that are
// distinct from the Primary Diagnosis, Secondary Diagnoses, and the HOPE
// Comorbidities checklist, each carrying an explicit clinician judgment
// (CONTRIBUTES_TO_TERMINAL_PROGNOSIS / CONTRIBUTES_TO_CLINICAL_BURDEN /
// DOES_NOT_MATERIALLY_CONTRIBUTE / UNABLE_TO_DETERMINE). Persisted at
// diagnoses.contributingConditions (array) -- the established
// formData.diagnoses.* JSONB namespace already used by every other field
// on this screen; no new table/column/migration.
//
// Documenting a condition here NEVER auto-adds it to Secondary Diagnoses
// and NEVER auto-checks a HOPE comorbidity box, in either direction --
// only nonblocking "already documented elsewhere" cross-reference notices
// are shown (findContributingConditionCrossReferences). An exact ICD-10
// duplicate within this list is blocked outright at selection time; a
// "probable" duplicate (same HOPE category, different code) is a
// nonblocking warning only, per owner directive ("warn, never silently
// merge"). Zero conditions is a valid, fully-complete state.
// ════════════════════════════════════════════════════════════════
function ContributingConditionRow({ condition, diagnosesData, onChange, onRequestRemove, styles, COLORS }) {
  const [searchText, setSearchText] = useState(() => (
    condition.icdDescription
      ? `${condition.icdDescription}${condition.icdCode ? ` (${formatIcd10Code(condition.icdCode)})` : ""}`
      : formatIcd10Code(condition.icdCode || "")
  ));
  const [duplicateError, setDuplicateError] = useState("");

  const requiresRationale = CONTRIBUTING_CONDITION_STATUSES_REQUIRING_RATIONALE.has(condition.contributionStatus);
  const incomplete = isContributingConditionIncomplete(condition);
  const crossRefs = condition.icdCode
    ? findContributingConditionCrossReferences(diagnosesData, condition.icdCode)
    : null;
  const probableDuplicates = condition.icdCode
    ? findProbableDuplicateContributingConditions(diagnosesData?.contributingConditions, condition.icdCode, condition.id)
    : [];

  const handleSelectSuggestion = (suggestion) => {
    const existing = findExactDuplicateContributingCondition(
      diagnosesData?.contributingConditions,
      suggestion.icd10_code,
      condition.id,
    );
    if (existing) {
      setDuplicateError(
        `${formatIcd10Code(suggestion.icd10_code)} is already documented as a contributing condition` +
          `${existing.icdDescription ? ` (${existing.icdDescription})` : ""}. Edit the existing entry instead of adding a duplicate.`,
      );
      return;
    }
    setDuplicateError("");
    // Apply both fields in a single patch -- two separate onChange("field", value)
    // calls here would each read the same pre-update `rows` closure in the
    // parent's touch() helper, so the second call would silently clobber the
    // first (icdCode would be lost, leaving only icdDescription persisted).
    onChange({ icdCode: suggestion.icd10_code, icdDescription: suggestion.diagnosis_description });
  };

  return (
    <div className="rnica-contributing-card" role="group" aria-label="Contributing condition">
      <div className="rnica-contributing-card__row1">
        <div className="rnica-diagnosis-card__search" role="cell">
          <Icd10DiagnosisInput
            value={searchText}
            onChange={setSearchText}
            onSelectSuggestion={handleSelectSuggestion}
            colors={{ cardBg: COLORS.white, border: COLORS.border, label: COLORS.gray, white: COLORS.dark }}
            inputStyle={styles.input}
            placeholder="Search diagnosis or ICD-10…"
          />
        </div>
        <Select value={condition.sourceType || "CLINICIAN_ENTERED"} onValueChange={(v) => onChange("sourceType", v)}>
          <SelectTrigger className="h-8 w-[220px] shrink-0 text-[12px]"><SelectValue /></SelectTrigger>
          <SelectContent>
            {CONTRIBUTING_CONDITION_SOURCE_OPTIONS.map((opt) => (
              <SelectItem key={opt.value} value={opt.value}>{opt.label}</SelectItem>
            ))}
          </SelectContent>
        </Select>
        <button
          type="button"
          className="rnica-diagnosis-card__remove"
          title="Remove this contributing condition"
          aria-label="Remove this contributing condition"
          onClick={onRequestRemove}
        >
          <span aria-hidden="true">×</span>
        </button>
      </div>

      {duplicateError && <div className="rnica-contributing-card__error" role="alert">{duplicateError}</div>}

      <div className="rnica-contributing-card__statuses" role="group" aria-label="Contribution status">
        {CONTRIBUTING_CONDITION_STATUS_OPTIONS.map((opt) => (
          <button
            key={opt.value}
            type="button"
            className={RNICA_CHIP_CLASS}
            data-state={condition.contributionStatus === opt.value ? "on" : "off"}
            onClick={() => onChange("contributionStatus", opt.value)}
          >
            {opt.label}
          </button>
        ))}
      </div>

      {requiresRationale && (
        <textarea
          className="rnica-contributing-card__rationale"
          style={{ ...styles.input, minHeight: 56, resize: "vertical", width: "100%" }}
          placeholder="Clinical rationale (required for this status)…"
          value={condition.clinicalRationale || ""}
          onChange={(e) => onChange("clinicalRationale", e.target.value)}
        />
      )}

      {(probableDuplicates.length > 0 || crossRefs?.inSecondaryDiagnoses || crossRefs?.hopeCategoryChecked) && (
        <div className="rnica-contributing-card__notice">
          {crossRefs?.inSecondaryDiagnoses && "Already documented as a Secondary Diagnosis. "}
          {crossRefs?.hopeCategoryChecked &&
            `Overlaps a checked HOPE comorbidity category (${crossRefs.hopeCategory?.shortLabel || crossRefs.hopeCategory?.label}). `}
          {probableDuplicates.length > 0 &&
            "Another contributing condition in the same comorbidity category is already documented — confirm this is a distinct condition, not a duplicate entry."}
        </div>
      )}

      {incomplete && (
        <div className="rnica-contributing-card__incomplete">
          Incomplete — select a diagnosis and a contribution status{requiresRationale ? ", plus a clinical rationale" : ""} to finish documenting this condition.
        </div>
      )}

      {(condition.createdByName || condition.updatedByName) && (
        <div className="rnica-contributing-card__meta">
          {condition.createdByName &&
            `Added by ${condition.createdByName}${condition.createdAt ? ` on ${new Date(condition.createdAt).toLocaleDateString()}` : ""}`}
          {condition.updatedByName && condition.updatedAt && condition.updatedAt !== condition.createdAt &&
            ` · Updated by ${condition.updatedByName} on ${new Date(condition.updatedAt).toLocaleDateString()}`}
        </div>
      )}
    </div>
  );
}

function makeContributingConditionId() {
  if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") return crypto.randomUUID();
  return `cc-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
}

function ContributingConditionsCard({ diagnosesData, updateField, styles, COLORS, workspacePilot = false }) {
  const rows = diagnosesData?.contributingConditions || [];
  const [pendingRemoveId, setPendingRemoveId] = useState(null);

  const setRows = (next) => updateField("contributingConditions", next);
  const currentUserName = () => {
    const user = getCurrentUser();
    return user?.full_name || user?.name || "";
  };

  const addRow = () => {
    const nowIso = new Date().toISOString();
    setRows([
      ...rows,
      {
        id: makeContributingConditionId(),
        icdCode: "",
        icdDescription: "",
        contributionStatus: "",
        clinicalRationale: "",
        sourceType: "CLINICIAN_ENTERED",
        active: true,
        createdByName: currentUserName(),
        createdAt: nowIso,
        updatedByName: currentUserName(),
        updatedAt: nowIso,
      },
    ]);
  };

  const touch = (idx, patch) => {
    const nowIso = new Date().toISOString();
    setRows(rows.map((row, i) => (i === idx ? { ...row, ...patch, updatedByName: currentUserName(), updatedAt: nowIso } : row)));
  };

  // Empty/never-touched rows (just added, nothing searched yet) have no
  // documentation to lose -- remove outright instead of interrupting with
  // a confirmation, mirroring SecondaryDiagnosesCard's identical rule.
  // Any row that was actually documented is soft-removed (active: false)
  // rather than deleted outright, so the audit trail is preserved.
  const requestRemove = (idx) => {
    const row = rows[idx];
    if (!row?.icdCode && !row?.icdDescription) {
      setRows(rows.filter((_, i) => i !== idx));
      return;
    }
    setPendingRemoveId(row.id);
  };

  const confirmRemove = () => {
    const idx = rows.findIndex((row) => row.id === pendingRemoveId);
    if (idx === -1) { setPendingRemoveId(null); return; }
    const nowIso = new Date().toISOString();
    setRows(rows.map((row, i) => (i === idx ? {
      ...row,
      active: false,
      removedByName: currentUserName(),
      removedAt: nowIso,
    } : row)));
    setPendingRemoveId(null);
  };

  const activeRows = rows.filter((row) => row.active !== false);
  const pendingRow = rows.find((row) => row.id === pendingRemoveId);

  if (workspacePilot) {
    return (
      <div className="rnica-diagnosis-ledger">
        <div className="rnica-diagnosis-ledger__summary">
          <span className="rnica-diagnosis-ledger__heading">
            Contributing Conditions
            <InfoTooltip text="Conditions that are not the Primary Diagnosis, a Secondary Diagnosis, or a checked HOPE Comorbidity, but that materially affect terminal prognosis or clinical burden. Documenting a condition here never auto-adds it elsewhere, and zero documented conditions is a valid state." />
          </span>
          <strong>{activeRows.length} documented</strong>
        </div>
        {activeRows.length === 0 ? (
          <div className="rnica-diagnosis-ledger__empty">No contributing conditions documented. This is valid — not every patient has one.</div>
        ) : (
          <div className="rnica-diagnosis-cards" aria-label="Contributing conditions">
            {rows.map((row, idx) => (row.active === false ? null : (
              <ContributingConditionRow
                key={row.id || idx}
                condition={row}
                diagnosesData={diagnosesData}
                onChange={(field, value) => touch(idx, typeof field === "object" && field !== null ? field : { [field]: value })}
                onRequestRemove={() => requestRemove(idx)}
                styles={styles}
                COLORS={COLORS}
              />
            )))}
          </div>
        )}
        <div className="rnica-diagnosis-ledger__actions">
          <button type="button" onClick={addRow}>+ Add contributing condition</button>
        </div>

        <AlertDialog open={pendingRemoveId !== null} onOpenChange={(next) => { if (!next) setPendingRemoveId(null); }}>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>Remove this contributing condition?</AlertDialogTitle>
              <AlertDialogDescription>
                {pendingRow?.icdDescription || pendingRow?.icdCode
                  ? `"${pendingRow.icdDescription || formatIcd10Code(pendingRow.icdCode)}" will be removed from Contributing Conditions. The entry is kept in the audit history, not permanently erased.`
                  : "This entry will be removed."}
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel onClick={() => setPendingRemoveId(null)}>Cancel</AlertDialogCancel>
              <AlertDialogAction onClick={confirmRemove}>Remove</AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      </div>
    );
  }

  // Legacy (non-pilot) rendering -- plain inline-styled rows, no chip/Sheet
  // visual language, consistent with every other legacy branch on this
  // screen. Same data, same validation, same cross-reference notices.
  return (
    <div>
      <p style={{ fontSize: 12, color: COLORS.gray, marginTop: -4, marginBottom: 10 }}>
        Conditions that are not the Primary Diagnosis, a Secondary Diagnosis, or a checked HOPE
        Comorbidity, but that materially affect terminal prognosis or clinical burden. Documenting
        a condition here never auto-adds it to Secondary Diagnoses or the HOPE checklist.
      </p>
      {activeRows.length === 0 && (
        <div style={{ fontSize: 12.5, color: COLORS.gray, fontStyle: "italic", marginBottom: 10 }}>
          No contributing conditions documented.
        </div>
      )}
      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        {rows.map((row, idx) => {
          if (row.active === false) return null;
          const requiresRationale = CONTRIBUTING_CONDITION_STATUSES_REQUIRING_RATIONALE.has(row.contributionStatus);
          const incomplete = isContributingConditionIncomplete(row);
          return (
            <div key={row.id || idx} style={{ padding: "8px 10px", borderRadius: 8, border: `1px solid ${COLORS.border}`, background: COLORS.bg }}>
              <div style={{ display: "grid", gridTemplateColumns: "140px minmax(0, 1fr) auto", gap: 10, alignItems: "center", marginBottom: 8 }}>
                <input
                  style={styles.input}
                  placeholder="ICD-10"
                  value={row.icdCode || ""}
                  onChange={(e) => touch(idx, { icdCode: e.target.value })}
                />
                <input
                  style={styles.input}
                  placeholder="Description"
                  value={row.icdDescription || ""}
                  onChange={(e) => touch(idx, { icdDescription: e.target.value })}
                />
                <button type="button" style={{ ...styles.btnDanger, padding: "6px 10px" }} onClick={() => requestRemove(idx)}>
                  Remove
                </button>
              </div>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 8 }}>
                <select style={styles.input} value={row.contributionStatus || ""} onChange={(e) => touch(idx, { contributionStatus: e.target.value })}>
                  <option value="">— select contribution status —</option>
                  {CONTRIBUTING_CONDITION_STATUS_OPTIONS.map((opt) => (
                    <option key={opt.value} value={opt.value}>{opt.label}</option>
                  ))}
                </select>
                <select style={styles.input} value={row.sourceType || "CLINICIAN_ENTERED"} onChange={(e) => touch(idx, { sourceType: e.target.value })}>
                  {CONTRIBUTING_CONDITION_SOURCE_OPTIONS.map((opt) => (
                    <option key={opt.value} value={opt.value}>{opt.label}</option>
                  ))}
                </select>
              </div>
              {requiresRationale && (
                <textarea
                  style={{ ...styles.input, minHeight: 56, resize: "vertical", width: "100%" }}
                  placeholder="Clinical rationale (required for this status)…"
                  value={row.clinicalRationale || ""}
                  onChange={(e) => touch(idx, { clinicalRationale: e.target.value })}
                />
              )}
              {incomplete && (
                <p style={{ fontSize: 11.5, color: COLORS.red || "#DC2626", marginTop: 6 }}>
                  Incomplete — select a diagnosis and a contribution status{requiresRationale ? ", plus a clinical rationale" : ""}.
                </p>
              )}
            </div>
          );
        })}
      </div>
      <button type="button" style={{ ...styles.btnSecondary, marginTop: 10 }} onClick={addRow}>
        + Add Contributing Condition
      </button>
      {pendingRemoveId !== null && (
        <div style={{ marginTop: 10, padding: 10, border: `1px solid ${COLORS.border}`, borderRadius: 8, background: COLORS.bg }}>
          <p style={{ fontSize: 12.5, marginBottom: 8 }}>
            Remove {pendingRow?.icdDescription || formatIcd10Code(pendingRow?.icdCode || "") || "this entry"}?
          </p>
          <button type="button" style={{ ...styles.btnDanger, marginRight: 8 }} onClick={confirmRemove}>Remove</button>
          <button type="button" style={styles.btnSecondary} onClick={() => setPendingRemoveId(null)}>Cancel</button>
        </div>
      )}
    </div>
  );
}

// ════════════════════════════════════════════════════════════════
// SKIN / WOUND — Structured wound documentation (Master Map §5.11).
//
// PRODUCT OWNER DECISION (2026-11-19) "Option A — Safer Filtered-Views
// Approach": `skin.wounds[]` remains the ONE physical storage collection
// (already wired to structuredFindingRegistry.generated.js AI evidence-
// harvesting targets, backend poc_compiler_rn_mapper.py keyword mapping,
// and domain/body-systems/ownership.ts fact keys — forking into two new
// arrays would orphan all three). The schema is expanded ADDITIVELY
// (every pre-existing field/path untouched) and rendered as two clinically
// separate, independently filtered views:
//   - PressureInjuryWoundsCard ("Pressure Ulcers / Injuries")
//   - OtherWoundsCard ("Other Wounds / Skin Conditions")
// Both read/write the SAME `wounds` array, keyed by a new stable `woundId`
// (never array position), and classify each row by a new `conditionType`
// discriminator (never a boolean alone — a boolean cannot distinguish the
// 13 non-pressure-injury condition types Layer 3B requires). Rows saved
// before `conditionType` existed are inferred ONLY from already-structured
// markers (`presentAsPressureInjury`, `stage`, `isSkinTear`,
// `isSurgicalWound`, `woundType`) — never guessed from free text — and
// anything that still can't be classified surfaces in a "Needs
// Classification" bucket inside Other Wounds rather than being hidden.
// Wound Count is intentionally derived (rows.length), not a separate
// manual field, so it can never drift out of sync with the actual
// documented wounds (same "reuse, don't duplicate" rule applied to BMI).
// Pressure-relief measures and repositioning plan are plan-level (not
// per-wound) and are rendered as ordinary fields on the existing
// "Pressure Relief & Comfort" card — see SECTION_CONFIGS.skin.
// ════════════════════════════════════════════════════════════════
function makeWoundId() {
  if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") return crypto.randomUUID();
  return `wnd-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
}

