const LEGACY_WOUND_TYPE_TO_CONDITION_TYPE = {
  "Pressure injury": WOUND_CONDITION_TYPES.PRESSURE_INJURY,
  "Skin tear": WOUND_CONDITION_TYPES.SKIN_TEAR,
  "Surgical wound": WOUND_CONDITION_TYPES.SURGICAL_WOUND,
  "Venous ulcer": WOUND_CONDITION_TYPES.VENOUS_ULCER,
  "Arterial ulcer": WOUND_CONDITION_TYPES.ARTERIAL_ULCER,
  "Diabetic ulcer": WOUND_CONDITION_TYPES.DIABETIC_FOOT_ULCER,
  "Nonhealing wound": WOUND_CONDITION_TYPES.OTHER_NON_PRESSURE_ULCER,
  "Other": WOUND_CONDITION_TYPES.OTHER_SKIN_CONDITION,
};

// Reliable-inference-only derivation (Product Owner Directive Steps 6/7):
// infer `conditionType` ONLY from markers already structured on the row;
// never guessed from free text. Falls back to "unknown_legacy" so a
// pre-existing record is never silently reclassified.
function inferLegacyWoundConditionType(w) {
  if (w?.conditionType) return w.conditionType;
  if (w?.presentAsPressureInjury || (w?.stage && w.stage !== "N/A")) return WOUND_CONDITION_TYPES.PRESSURE_INJURY;
  if (w?.isSkinTear) return WOUND_CONDITION_TYPES.SKIN_TEAR;
  if (w?.isSurgicalWound) return WOUND_CONDITION_TYPES.SURGICAL_WOUND;
  if (w?.woundType && LEGACY_WOUND_TYPE_TO_CONDITION_TYPE[w.woundType]) return LEGACY_WOUND_TYPE_TO_CONDITION_TYPE[w.woundType];
  return WOUND_CONDITION_TYPES.UNKNOWN_LEGACY;
}

function isPressureInjuryWound(w) {
  return inferLegacyWoundConditionType(w) === WOUND_CONDITION_TYPES.PRESSURE_INJURY;
}

// PRODUCT OWNER CORRECTION "Remove the open-each-wound model" -- the
// inventory/card title must lead with LOCATION (e.g. "#1 Coccyx"), never
// condition type (not "#1 Pressure Injury"). Condition type/stage is
// still shown, but demoted to a secondary line. This label is only for
// that secondary line.
function getConditionTypeDisplayLabel(conditionType, variant) {
  if (variant === "pressureInjury" || conditionType === WOUND_CONDITION_TYPES.PRESSURE_INJURY) return "Pressure Injury";
  if (conditionType === WOUND_CONDITION_TYPES.UNKNOWN_LEGACY || !conditionType) return "Wound / Skin Condition";
  const match = OTHER_WOUND_CONDITION_TYPE_OPTIONS.find((o) => o.value === conditionType);
  return match ? match.label : "Wound / Skin Condition";
}

