// Broad body-region list for condition types that may genuinely present
// almost anywhere (Rash, Bruising, Surgical Wound, Malignant/Fungating
// Wound, Open Lesion, Other Skin Condition) and for unclassified legacy
// rows -- deliberately NOT restricted the way the site-specific ulcer
// types above are, per "do not over-restrict conditions that may occur
// at multiple sites."
const BROAD_WOUND_LOCATION_OPTIONS = [
  "Head/Scalp", "Face", "Neck", "Chest", "Abdomen", "Back",
  "Upper Arm", "Forearm", "Hand", "Buttocks/Perineum", "Thigh", "Lower Leg", "Foot", "Other",
];
// Condition Type -> allowed Location options. Pressure Injury keeps the
// existing anatomically-complete pressure-point list; every other
// condition type gets exactly the site-appropriate subset above.
function woundLocationOptionsForConditionType(conditionType) {
  switch (conditionType) {
    case WOUND_CONDITION_TYPES.PRESSURE_INJURY: return PI_LOCATION_OPTIONS;
    case WOUND_CONDITION_TYPES.DIABETIC_FOOT_ULCER: return DIABETIC_FOOT_ULCER_LOCATION_OPTIONS;
    case WOUND_CONDITION_TYPES.VENOUS_ULCER: return VENOUS_ULCER_LOCATION_OPTIONS;
    case WOUND_CONDITION_TYPES.ARTERIAL_ULCER: return ARTERIAL_ULCER_LOCATION_OPTIONS;
    case WOUND_CONDITION_TYPES.SKIN_TEAR: return SKIN_TEAR_LOCATION_OPTIONS;
    case WOUND_CONDITION_TYPES.MASD:
    case WOUND_CONDITION_TYPES.EXCORIATION:
      return MASD_EXCORIATION_LOCATION_OPTIONS;
    default: return BROAD_WOUND_LOCATION_OPTIONS;
  }
}

