      if (side === LOCATION_SIDE_VALUES.LEFT) return MAP_AREA.LEFT_LOWER_EXTREMITY;
      if (side === LOCATION_SIDE_VALUES.RIGHT) return MAP_AREA.RIGHT_LOWER_EXTREMITY;
