// still targets these exact paths per
// structuredFindingRegistry.generated.js and is NOT modified by this
// change) are never deleted -- they surface here, read-only, only when
// populated.
function EndocrineLegacyTreatmentReferenceCard({ currentEndocrineMeds, insulinType, insulinDose, oralHypoglycemics, lastHbA1c, lastHbA1cDate, thyroidNotes, styles, COLORS }) {
  const hasMeds = (currentEndocrineMeds || []).length > 0;
  const hasOralHypoglycemics = (oralHypoglycemics || []).length > 0;
  const hasHbA1c = Boolean(lastHbA1c || lastHbA1cDate);
  const hasThyroidNotes = Boolean(thyroidNotes);
  if (!hasMeds && !insulinType && !insulinDose && !hasOralHypoglycemics && !hasHbA1c && !hasThyroidNotes) return null;
  return (
    <div style={styles.infoBox}>
      {hasMeds && (
        <div>
          Legacy Endocrine Medications: {currentEndocrineMeds.join(", ")}
        </div>
      )}
      {(insulinType || insulinDose) && (
        <div style={{ marginTop: hasMeds ? 6 : 0 }}>
          Legacy Insulin: {[insulinType, insulinDose].filter(Boolean).join(" — ")}
        </div>
      )}
      {hasOralHypoglycemics && (
        <div style={{ marginTop: (hasMeds || insulinType || insulinDose) ? 6 : 0 }}>
          Legacy Oral Hypoglycemics: {oralHypoglycemics.join(", ")}
        </div>
      )}
      {hasHbA1c && (
        <div style={{ marginTop: (hasMeds || insulinType || insulinDose || hasOralHypoglycemics) ? 6 : 0 }}>
          Legacy HbA1c: {[lastHbA1c, lastHbA1cDate].filter(Boolean).join(" — ")}
        </div>
      )}
      {hasThyroidNotes && (
        <div style={{ marginTop: (hasMeds || insulinType || insulinDose || hasOralHypoglycemics || hasHbA1c) ? 6 : 0 }}>
          Legacy Thyroid Notes: {thyroidNotes}
        </div>
      )}
      <div style={{ fontSize: 11, color: COLORS.gray, marginTop: 4 }}>
        Historical/voice-extracted entry — medication and treatment orders are managed under Medications / Tx-Meds-DME / Physician Orders, not here. HbA1c reflects long-term diabetes control and is not a core hospice assessment focus. Narrative documentation now belongs in Endocrine Notes.
      </div>
    </div>
  );
}

