function WoundMarker({ x, y, label, woundName, stage, onClick, isSelected }) {
  const calloutX = x > 90 ? x - 85 : x + 18;
  return (
    <g onClick={onClick} style={{ cursor: "pointer" }}>
      <circle cx={x} cy={y} r={14} fill={BODY_MAP_COLORS.woundGlow} />
      <circle cx={x} cy={y} r={8} fill={BODY_MAP_COLORS.wound} stroke="#FFF" strokeWidth={2} />
      <text x={x} y={y + 3.5} textAnchor="middle" fontSize={9} fontWeight={800} fill="#FFF" style={{ pointerEvents: "none" }}>
        {label}
      </text>
      {isSelected && (
        <>
          <line x1={x > 90 ? x - 8 : x + 8} y1={y} x2={calloutX + (x > 90 ? 65 : 0)} y2={y - 10} stroke={BODY_MAP_COLORS.wound} strokeWidth={1} opacity={0.7} />
          <rect x={calloutX} y={y - 32} width={70} height={28} rx={4} fill={BODY_MAP_COLORS.card} stroke={BODY_MAP_COLORS.wound} strokeWidth={1} />
          <text x={calloutX + 6} y={y - 18} fontSize={8} fill={BODY_MAP_COLORS.text} fontWeight={600}>{woundName}</text>
          <text x={calloutX + 6} y={y - 9} fontSize={7} fill={BODY_MAP_COLORS.textMuted}>Stage {stage}</text>
        </>
      )}
    </g>
  );
}

function BodyMap({ value = [], tone = "pain", patientType = "verbal", onPatientTypeChange, onToggle, onClearAll, figureMaxWidth }) {
  const [view, setView] = useState("both");
  const { mode: themeMode } = useThemeMode();
  const COLORS = useMemo(() => getRnicaColors(themeMode), [themeMode]);
  const selectedRegions = Array.isArray(value) ? value : [];

  const bodyTypeButtons = [
    { label: "Verbal / able to self-report", value: "verbal" },
    { label: "Non-verbal / unable to self-report", value: "non-verbal" },
    { label: "Pediatric / child", value: "pediatric" },
  ];

  const viewLabelMap = {
    both: "Anterior (Front) / Posterior (Back)",
    front: "Anterior (Front)",
    back: "Posterior (Back)",
  };

  return (
    <div style={{ marginBottom: 16 }}>
      {onPatientTypeChange && (
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 12 }}>
          {bodyTypeButtons.map((option) => (
            <button
              key={option.value}
              type="button"
              onClick={() => onPatientTypeChange(option.value)}
              style={{
                borderRadius: 999,
                border: patientType === option.value ? `1px solid ${COLORS.teal}` : `1px solid ${COLORS.border}`,
                background: patientType === option.value ? (tone === "skin" ? COLORS.warningBoxBg : COLORS.tealBg) : COLORS.white,
                color: COLORS.dark,
                fontSize: 11,
                fontWeight: 700,
                padding: "5px 10px",
                cursor: "pointer",
              }}
            >
              {option.label}
            </button>
          ))}
        </div>
      )}

      <div style={{ marginBottom: 12 }}>
        <div style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          gap: 12,
          flexWrap: "wrap",
          padding: "8px 10px",
          background: COLORS.mapControlBg,
          border: `1px solid ${COLORS.mapControlBorder}`,
          borderRadius: 12,
          boxShadow: "inset 0 1px 2px rgba(15, 23, 42, 0.04)",
        }}>
          <div style={{
            fontSize: 11,
            fontWeight: 800,
            letterSpacing: "0.08em",
            textTransform: "uppercase",
            color: COLORS.mapMuted,
          }}>
            Body view
          </div>

          <div style={{
            fontSize: 12,
            fontWeight: 800,
            color: COLORS.mapChipText,
            background: COLORS.mapChipBg,
            border: `1px solid ${COLORS.mapControlBorder}`,
            borderRadius: 8,
            padding: "6px 10px",
            minWidth: 190,
            textAlign: "center",
          }}>
            {viewLabelMap[view] || "Anterior (Front) / Posterior (Back)"}
          </div>

          <div style={{
            display: "flex",
            alignItems: "center",
            gap: 8,
            flexWrap: "wrap",
          }}>
            {[
              { label: "Both", value: "both" },
              { label: "Front", value: "front" },
              { label: "Back", value: "back" },
            ].map((option) => (
              <button
                key={option.value}
                type="button"
                onClick={() => setView(option.value)}
                style={{
                  borderRadius: 8,
                  border: view === option.value ? `1px solid ${COLORS.teal}` : "1px solid transparent",
                  background: view === option.value ? COLORS.tealBg : "transparent",
                  color: view === option.value ? COLORS.mapChipText : COLORS.mapMuted,
                  fontSize: 11,
                  fontWeight: 700,
                  padding: "7px 12px",
                  cursor: "pointer",
                  transition: "all 0.15s ease",
                }}
              >
                {option.label}
              </button>
            ))}
          </div>
        </div>
      </div>

      <BodyMapPain
        selectedRegions={selectedRegions}
        onToggleRegion={(regionId) => onToggle?.(regionId)}
        onClearAll={onClearAll}
        view={view}
        maxWidth={figureMaxWidth}
      />
    </div>
  );
}

// Owner directive (2026-10-03) "Comprehensive Pain Assessment Date
// auto-population" -- the nurse no longer manually confirms a
// "Comprehensive pain assessment completed" checkbox or re-enters a date;
// the comprehensive assessment date defaults to (and is kept live in sync
// with, via the useEffect near handleLock) the parent RNICA visit date
// (`visitMeta.visitDate`). The only way the two values ever diverge is an
// explicit, reason-documented override, entered through this component.
// `comprehensiveAssessmentCompleted` (HOPE J0910.A) remains a real stored
// field -- it is now derived automatically (true once a date is present)
// by that same sync effect, instead of requiring separate manual entry.
function ComprehensivePainAssessmentDateField({ label, value, parentVisitDate, overrideReason, hopeCode, onDateChange, onReasonChange, onClearOverride, styles, COLORS }) {
  const [overriding, setOverriding] = useState(Boolean(overrideReason));
  const displayDate = value || parentVisitDate;

  if (!overriding) {
    return (
      <div style={styles.formGroup}>
        <label style={styles.label}>
          {label} {hopeCode && <> <HopeTag code={hopeCode} /></>}
        </label>
        <div style={{ display: "flex", alignItems: "baseline", gap: 10, flexWrap: "wrap" }}>
          <span style={{ fontSize: 13.5, color: COLORS.dark, fontWeight: 600 }}>
            {formatDate(displayDate)}
          </span>
          <span style={{ fontSize: 11, color: COLORS.gray }}>
            (auto-filled from RNICA assessment date)
          </span>
          <button
            type="button"
            onClick={() => setOverriding(true)}
            style={{
              background: "none", border: "none", padding: 0, cursor: "pointer",
              fontSize: 11.5, color: COLORS.teal, fontWeight: 600, textDecoration: "underline",
            }}
          >
            Document a different date
          </button>
        </div>
      </div>
    );
  }

  return (
    <div style={{ ...styles.formGroup, border: `1px solid ${COLORS.border}`, borderRadius: 8, padding: 10 }}>
      <label style={styles.label}>
        {label} {hopeCode && <> <HopeTag code={hopeCode} /></>}
      </label>
      <FormInput
        label="Comprehensive assessment date (override)"
        type="date"
        value={value}
        onChange={onDateChange}
      />
      <FormInput
        label="Reason date differs from RNICA assessment date"
        required
        value={overrideReason}
        onChange={onReasonChange}
        placeholder="Required to document an override"
      />
      <button
        type="button"
        onClick={() => {
          onClearOverride?.();
          setOverriding(false);
        }}
        style={{
          background: "none", border: "none", padding: 0, cursor: "pointer",
          fontSize: 11.5, color: COLORS.gray, fontWeight: 600, textDecoration: "underline",
        }}
      >
        Revert to RNICA assessment date
      </button>
    </div>
  );
}

// Body map is a secondary interaction: the Pain screen's primary surface
// only ever shows a one-line summary + "Edit body map" button. The full
// interactive silhouette (BodyMap above) only exists inside this Dialog,
// so it never consumes vertical space in the normal page flow -- opened
// on demand, closed by default, same data/onToggle contract as before.
function PainBodyMapDialogField({ value = [], onToggle, onClearAll, regionLabelById }) {
  const [open, setOpen] = useState(false);
  const selected = Array.isArray(value) ? value : [];
  const summaryText = selected.length
    ? selected.map((id) => regionLabelById?.[id] || id).join(", ")
    : "No body map location documented";

  return (
    <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10, flexWrap: "wrap" }}>
      <div style={{ fontSize: 12, color: "var(--sns-text, inherit)", flex: 1, minWidth: 160 }}>
        <strong style={{ fontWeight: 700 }}>Body map: </strong>{summaryText}
      </div>
      <button
        type="button"
        onClick={() => setOpen(true)}
        className="rnica-pain-bodymap-edit-btn"
        style={{
          borderRadius: 8,
          border: "1px solid var(--sns-teal, #0d9488)",
          background: "transparent",
          // Bug fix (Pain Sheet UI polish pass): no color was set here, so
          // the launch button silently inherited a near-black default and
          // was nearly invisible against the dark theme. Brighter accent
          // text (same teal used for the border) makes the trigger action
          // immediately visible without changing the Body Map dialog itself.
          color: "var(--sns-teal, #0d9488)",
          fontSize: 11.5,
          fontWeight: 700,
          padding: "6px 12px",
          cursor: "pointer",
          whiteSpace: "nowrap",
        }}
      >
        {selected.length ? "Edit body map" : "Add body map location"}
      </button>

      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent className="sm:max-w-xl">
          <DialogHeader>
            <DialogTitle>Pain — Body Map</DialogTitle>
            <DialogDescription>Select every region where the patient reports or shows pain.</DialogDescription>
          </DialogHeader>
          <BodyMap value={selected} tone="pain" onToggle={onToggle} onClearAll={onClearAll} />
          <DialogFooter>
            <button
              type="button"
              onClick={() => setOpen(false)}
              style={{
                borderRadius: 8,
                border: "1px solid var(--sns-teal, #0d9488)",
                background: "var(--sns-teal, #0d9488)",
                color: "#fff",
                fontSize: 12.5,
                fontWeight: 700,
                padding: "8px 16px",
                cursor: "pointer",
              }}
            >
              Done
            </button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

